INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C1','sci',4,1,'u4',1,'생물 놀이 카드 놀이 차례 — 카드를 섞어 세 장씩 나누기 → 카드를 보여 주며 이름 말하기 → 같은 카드면 가져오고 아니면 가운데 카드 한 장 → 모은 카드를 동물·식물·그 밖의 생물로 나누기 · 이기고 지기보다 여러 생물에 관심',ARRAY['[4과12-01] 균류, 원생생물, 세균을 관찰하여 특징과 사는 곳을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C2','sci',4,1,'u4',1,'동물과 식물을 나누는 기준 — 동물 = 스스로 움직임 · 식물 = 뿌리·줄기·잎이 있음 · 색깔·크기·사는 곳은 기준이 아님',ARRAY['[4과12-01] 균류, 원생생물, 세균을 관찰하여 특징과 사는 곳을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C3','sci',4,1,'u4',1,'그 밖의 생물 — 동물에도 식물에도 넣기 어려운 생물 — 버섯·곰팡이·해캄·짚신벌레·미역 등 · 생물은 동물과 식물 두 가지만이 아님',ARRAY['[4과12-01] 균류, 원생생물, 세균을 관찰하여 특징과 사는 곳을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C4','sci',4,1,'u4',1,'버섯을 식물로 넣기 어려운 까닭 — 움직이지 않지만 뿌리·줄기·잎이 없음 · 갓·자루는 잎·줄기와 다름',ARRAY['[4과12-01] 균류, 원생생물, 세균을 관찰하여 특징과 사는 곳을 설명할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
