INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C49','sci',4,1,'u4',7,'생물 농약 — 특정한 해충에게만 질병을 일으키는 곰팡이나 세균으로 만든 농약 — 다른 생물에게 피해를 주지 않아 친환경',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C50','sci',4,1,'u4',7,'편지 속 낱말 놀이 — 문장이 옳은지 틀린지 판단하며 단원 개념을 확인 · 틀린 문장은 옳은 내용으로 고침',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C51','sci',4,1,'u4',8,'생명과학 연구원 — 생물 연구로 다양한 생명 현상을 탐구 · 사람·동물·식물은 물론 눈에 보이지 않는 생물까지 · 의료·환경·전자·기계 등 다른 분야와 힘을 합함',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C52','sci',4,1,'u4',8,'연구원이 하는 일 네 갈래 — 바이오 에너지(버려지는 물질로 전기, 친환경 연료) · 새로운 품종(식량 부족 대비, 병·해충에 강한 작물) · 의약품(독성이 낮고 부작용이 적은 편) · 질병 분석과 치료(생물 정보 수집·분석)',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C53','sci',4,1,'u4',8,'이로운 세균을 이용한 연구 — 건강한 사람에게 기증받은 대변에서 이로운 세균을 걸러 내어 환자의 장 속에 넣어 치료를 도움 — 세균이 늘 해로운 것은 아님',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC4-1-u4-C54','sci',4,1,'u4',8,'배운 생물과 진로 생각 — 균류(약 연구)·원생생물(연료 연구)·세균(치료 연구)이 연구로 이어짐 · 하고 싶은 연구에 정답은 없고 풀고 싶은 문제를 떠올림',ARRAY['[4과12-03] 생명과학이 우리 생활에 이용된 사례를 조사하여 공유할 수 있다(지도서 성취기준 초안 · W7 확인)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X01','sci',4,'u4',ARRAY['SC4-1-u4-C3']::text[],'생물은 동물과 식물 두 가지뿐이라고 여기거나 그 밖의 생물을 생물로 보지 않는다','그 밖의 생물도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X02','sci',4,'u4',ARRAY['SC4-1-u4-C4','SC4-1-u4-C12']::text[],'움직이지 않으면 식물이라고 여겨 버섯을 식물로 나눈다','뿌리·줄기·잎을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X03','sci',4,'u4',ARRAY['SC4-1-u4-C5','SC4-1-u4-C22']::text[],'초록색이거나 스스로 양분을 만들면 식물이라고 여겨 해캄을 식물로 나눈다','뿌리·줄기·잎이 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X04','sci',4,'u4',ARRAY['SC4-1-u4-C2']::text[],'색깔·크기·사는 곳으로 동물과 식물을 나누려 한다','움직임 · 뿌리·줄기·잎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X05','sci',4,'u4',ARRAY['SC4-1-u4-C6']::text[],'그 밖의 생물은 아주 먼 곳에만 있거나 우리 주변에는 없다고 여긴다','우리 주변 어디에나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X06','sci',4,'u4',ARRAY['SC4-1-u4-C1']::text[],'카드 놀이의 차례를 잘못 알거나 이기고 지는 것만 생각한다','나누기가 목적') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X07','sci',4,'u4',ARRAY['SC4-1-u4-C12']::text[],'곰팡이는 솜털이나 먼지일 뿐 생물이 아니라고 여긴다','균사가 있는 생물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X08','sci',4,'u4',ARRAY['SC4-1-u4-C14']::text[],'곰팡이는 아무것도 없던 곳에서 갑자기 저절로 생긴다고 여긴다','보이지 않던 포자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X09','sci',4,'u4',ARRAY['SC4-1-u4-C10']::text[],'균류가 씨·꽃·알로 번식한다고 여긴다','포자로 번식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X10','sci',4,'u4',ARRAY['SC4-1-u4-C11']::text[],'균류가 식물처럼 스스로 양분을 만든다고 여긴다','다른 생물에서 얻어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X11','sci',4,'u4',ARRAY['SC4-1-u4-C13']::text[],'균류가 메마르거나 춥거나 햇빛이 강한 곳에서 잘 자란다고 여긴다','습하고 따뜻한 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X12','sci',4,'u4',ARRAY['SC4-1-u4-C7','SC4-1-u4-C9','SC4-1-u4-C10']::text[],'균사·포자·갓·자루의 뜻을 뒤바꾼다','실 모양 균사 · 자손 포자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X13','sci',4,'u4',ARRAY['SC4-1-u4-C8']::text[],'맨눈으로만 보아도 충분하다고 여기거나 관찰 도구의 차례를 거꾸로 한다','맨눈 → 돋보기 → 현미경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X14','sci',4,'u4',ARRAY['SC4-1-u4-C15']::text[],'버섯·곰팡이 관찰 안전(마스크·장갑·냄새·먹지 않기·손 씻기)을 지키지 않는다','먹지 않고 손 씻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X15','sci',4,'u4',ARRAY['SC4-1-u4-C19']::text[],'원생생물을 동물·식물·균류 가운데 하나로 넣는다','어디에도 속하지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X16','sci',4,'u4',ARRAY['SC4-1-u4-C20']::text[],'원생생물이 메마른 땅에 살거나 바다에는 살지 않는다고 여긴다','주로 물에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X17','sci',4,'u4',ARRAY['SC4-1-u4-C16','SC4-1-u4-C17','SC4-1-u4-C18']::text[],'해캄과 짚신벌레의 생김새·특징을 뒤바꾼다','해캄 양분 · 짚신벌레 움직임') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X18','sci',4,'u4',ARRAY['SC4-1-u4-C19']::text[],'원생생물에 균사가 있다고 여겨 균류와 헷갈린다','균사는 균류') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X19','sci',4,'u4',ARRAY['SC4-1-u4-C21']::text[],'원생생물은 생김새가 모두 같아 생김새만으로 쉽게 묶을 수 있다고 여긴다','종류가 아주 많아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X20','sci',4,'u4',ARRAY['SC4-1-u4-C23']::text[],'작고 단순한 생물은 생물이 아니라거나 함부로 다뤄도 된다고 여긴다','작아도 생명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X21','sci',4,'u4',ARRAY['SC4-1-u4-C28']::text[],'세균은 눈에 보이지 않으니 생물이 아니라고 여긴다','양분 · 수가 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X22','sci',4,'u4',ARRAY['SC4-1-u4-C27']::text[],'세균은 더러운 곳에서만 산다고 여긴다','어디에나 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X23','sci',4,'u4',ARRAY['SC4-1-u4-C26']::text[],'세균이 맨눈으로 보이거나 균류·원생생물보다 크다고 여긴다','가장 작아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X24','sci',4,'u4',ARRAY['SC4-1-u4-C25']::text[],'세균의 모양을 실 모양 등으로 잘못 알거나 세균과 모양을 뒤바꾼다','공 · 막대 · 나선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X25','sci',4,'u4',ARRAY['SC4-1-u4-C29']::text[],'세균은 조건과 상관없이 늘거나 차가운 곳에서 더 잘 늘어난다고 여긴다','따뜻하면 빨리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X26','sci',4,'u4',ARRAY['SC4-1-u4-C24']::text[],'세균을 균류·원생생물과 헷갈린다(곰팡이·해캄을 세균으로)','세균은 따로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X27','sci',4,'u4',ARRAY['SC4-1-u4-C30']::text[],'죽은 생물이 썩는 것은 나쁜 일일 뿐이라고 여긴다','분해로 깨끗해져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X28','sci',4,'u4',ARRAY['SC4-1-u4-C35','SC4-1-u4-C36']::text[],'균류·원생생물·세균은 우리 생활과 관계가 없거나 해롭기만 하다고 여긴다','영향이 다양해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X29','sci',4,'u4',ARRAY['SC4-1-u4-C31','SC4-1-u4-C33']::text[],'생물이 미치는 영향과 무리를 뒤바꾼다(원생생물로 치즈, 세균이 적조, 균류가 산소)','무리별 영향') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X30','sci',4,'u4',ARRAY['SC4-1-u4-C34']::text[],'적조 현상의 뜻이나 원인을 잘못 안다','원생생물 수가 갑자기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC4-1-u4-X31','sci',4,'u4',ARRAY['SC4-1-u4-C31']::text[],'발효의 뜻이나 발효 음식에 이용한 생물을 뒤바꾼다','곰팡이·세균으로 음식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
