INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#1','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C3',1,'mc','auto','생물 놀이 카드에서 「그 밖의 생물」로 나눌 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C3","difficulty":1,"kind":"mc","stem":"생물 놀이 카드에서 「그 밖의 생물」로 나눌 수 있는 것은 무엇인가요?","options":[{"t":"표고버섯","correct":true},{"t":"강아지","mis":"SC4-1-u4-X04"},{"t":"해바라기","mis":"SC4-1-u4-X04"},{"t":"붕어","mis":"SC4-1-u4-X04"}],"explanation":["동물도 식물도 아닌 것을 찾아요.","움직이지도 않고 잎도 없어요.","표고버섯이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#2','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C2',1,'mc','auto','동물을 식물과 나누는 특징으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C2","difficulty":1,"kind":"mc","stem":"동물을 식물과 나누는 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"스스로 움직인다","correct":true},{"t":"색깔이 초록색이다","mis":"SC4-1-u4-X04"},{"t":"물에서 산다","mis":"SC4-1-u4-X04"},{"t":"크기가 작다","mis":"SC4-1-u4-X04"}],"explanation":["강아지를 떠올려요.","스스로 다녀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#3','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C6',1,'ox','auto','버섯이나 곰팡이 같은 그 밖의 생물도 우리 주변에서 볼 수 있어요.',ARRAY['SC4-1-u4-X05']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C6","difficulty":1,"kind":"ox","stem":"버섯이나 곰팡이 같은 그 밖의 생물도 우리 주변에서 볼 수 있어요.","answer":"O","reason_options":[{"t":"죽은 나무나 오래된 빵처럼 가까운 곳에도 살기 때문에","correct":true},{"t":"그 밖의 생물은 아주 먼 곳에만 살기 때문에","mis":"SC4-1-u4-X05"}],"mis":"SC4-1-u4-X05","explanation":["오래된 빵을 떠올려요.","가까이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
