INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#6','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C4',2,'mc','auto','버섯을 식물이라고 하기 어려운 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X02','SC4-1-u4-X04']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C4","difficulty":2,"kind":"mc","stem":"버섯을 식물이라고 하기 어려운 까닭은 무엇인가요?","options":[{"t":"뿌리·줄기·잎이 없기 때문에","correct":true},{"t":"움직이지 않기 때문에","mis":"SC4-1-u4-X02"},{"t":"갈색이기 때문에","mis":"SC4-1-u4-X04"},{"t":"크기가 작기 때문에","mis":"SC4-1-u4-X04"}],"explanation":["식물에는 무엇이 있나요?","버섯에는 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#7','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C5',2,'ox','auto','해캄은 초록색이므로 식물이에요.',ARRAY['SC4-1-u4-X03']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C5","difficulty":2,"kind":"ox","stem":"해캄은 초록색이므로 식물이에요.","answer":"X","reason_options":[{"t":"초록색이어도 뿌리·줄기·잎이 없어 식물이라고 하기 어렵기 때문에","correct":true},{"t":"초록색인 생물은 모두 식물이기 때문에","mis":"SC4-1-u4-X03"}],"mis":"SC4-1-u4-X03","explanation":["색깔은 기준이 아니에요.","뿌리·줄기·잎을 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#8','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C1',2,'mc','auto','생물 놀이 카드 놀이의 마지막 단계에서 하는 일은 무엇인가요?',ARRAY['SC4-1-u4-X06']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C1","difficulty":2,"kind":"mc","stem":"생물 놀이 카드 놀이의 마지막 단계에서 하는 일은 무엇인가요?","options":[{"t":"모은 카드를 동물, 식물, 그 밖의 생물로 나눈다","correct":true},{"t":"카드를 가장 많이 모은 사람을 뽑는다","mis":"SC4-1-u4-X06"},{"t":"카드를 다시 섞어 나누어 가진다","mis":"SC4-1-u4-X06"},{"t":"모은 카드를 모두 버린다","mis":"SC4-1-u4-X06"}],"explanation":["④를 읽어요.","세 갈래로 나눠요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 카드를 모두 섞은 뒤 두 사람이 세 장씩 나누어 가졌다.","② 카드를 한 장씩 보여 주며 생물의 이름을 말했다.","③ 같은 카드면 가져오고, 아니면 가운데 카드를 한 장 가져왔다.","④ 모은 카드를 동물, 식물, 그 밖의 생물로 나누었다.","⑤ 표고버섯, 곰팡이, 해캄은 어디에도 넣기 어려웠다."],"title":"생물 놀이 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#9','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C3',2,'mc','auto','「그 밖의 생물」은 어떤 생물인가요?',ARRAY['SC4-1-u4-X04','SC4-1-u4-X01']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C3","difficulty":2,"kind":"mc","stem":"「그 밖의 생물」은 어떤 생물인가요?","options":[{"t":"동물에도 식물에도 넣기 어려운 생물","correct":true},{"t":"동물 가운데 크기가 작은 생물","mis":"SC4-1-u4-X04"},{"t":"식물 가운데 꽃이 없는 생물","mis":"SC4-1-u4-X04"},{"t":"살아 있지 않은 물체","mis":"SC4-1-u4-X01"}],"explanation":["세 갈래를 떠올려요.","둘 다 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_basic#10','sci',4,1,'u4','L01','g4_1_sci_u4_L01_basic','lesson_basic','SC4-1-u4-C3',3,'mc','auto','다음 가운데 「그 밖의 생물」끼리만 모은 것은 무엇인가요?',ARRAY['SC4-1-u4-X04','SC4-1-u4-X01']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C3","difficulty":3,"kind":"mc","stem":"다음 가운데 「그 밖의 생물」끼리만 모은 것은 무엇인가요?","options":[{"t":"곰팡이, 해캄, 미역","correct":true},{"t":"곰팡이, 소나무, 미역","mis":"SC4-1-u4-X04"},{"t":"해캄, 거북, 버섯","mis":"SC4-1-u4-X04"},{"t":"강아지, 해바라기, 붕어","mis":"SC4-1-u4-X01"}],"explanation":["하나씩 따져요.","소나무와 거북은 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#1','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C2',2,'blank','auto','「동물은 스스로 (      ), 식물은 뿌리·줄기·잎이 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C2","difficulty":2,"kind":"blank","stem":"「동물은 스스로 (      ), 식물은 뿌리·줄기·잎이 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"움직이고","correct":true},{"t":"초록색이고","mis":"SC4-1-u4-X04"},{"t":"물속에 살고","mis":"SC4-1-u4-X04"},{"t":"크기가 작고","mis":"SC4-1-u4-X04"}],"explanation":["동물의 특징이에요.","강아지를 떠올려요.","「움직이고」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#2','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C1',2,'mc','auto','생물 놀이 카드 놀이를 할 때 생각할 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X06']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C1","difficulty":2,"kind":"mc","stem":"생물 놀이 카드 놀이를 할 때 생각할 점으로 알맞은 것은 무엇인가요?","options":[{"t":"이기고 지는 것보다 여러 생물에 관심을 가진다","correct":true},{"t":"카드를 많이 모아 이기는 것만 생각한다","mis":"SC4-1-u4-X06"},{"t":"모르는 생물 카드는 몰래 버린다","mis":"SC4-1-u4-X06"},{"t":"친구 카드를 몰래 엿본다","mis":"SC4-1-u4-X06"}],"explanation":["놀이의 목적을 떠올려요.","생물을 알아 가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#3','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C4',3,'error','auto','친구들이 버섯에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X02','SC4-1-u4-X04','SC4-1-u4-X01']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 버섯에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「버섯은 움직이지 않으니까 식물이야.」","correct":true,"mis_target":"SC4-1-u4-X02"},{"t":"친구 가 — 「버섯에는 뿌리·줄기·잎이 없어.」","mis":"SC4-1-u4-X04"},{"t":"친구 다 — 「버섯은 그 밖의 생물로 나눌 수 있어.」","mis":"SC4-1-u4-X01"}],"explanation":["움직임만 보면 안 돼요.","뿌리·줄기·잎을 봐요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#4','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C5',3,'mc','auto','해캄과 소나무를 견줄 때 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X03','SC4-1-u4-X04']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C5","difficulty":3,"kind":"mc","stem":"해캄과 소나무를 견줄 때 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"소나무는 뿌리·줄기·잎이 있지만 해캄은 없다","correct":true},{"t":"해캄은 초록색이고 소나무는 초록색이 아니다","mis":"SC4-1-u4-X03"},{"t":"둘 다 뿌리·줄기·잎이 있다","mis":"SC4-1-u4-X03"},{"t":"해캄은 걸어 다니고 소나무는 못 움직인다","mis":"SC4-1-u4-X04"}],"explanation":["둘 다 초록색이에요.","다른 점을 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
