INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#6','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C3',3,'ox','auto','생물은 동물과 식물, 두 가지로만 나눌 수 있어요.',ARRAY['SC4-1-u4-X01']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C3","difficulty":3,"kind":"ox","stem":"생물은 동물과 식물, 두 가지로만 나눌 수 있어요.","answer":"X","reason_options":[{"t":"동물에도 식물에도 넣기 어려운 그 밖의 생물이 있기 때문에","correct":true},{"t":"움직이지 않는 생물은 모두 식물이기 때문에","mis":"SC4-1-u4-X01"}],"mis":"SC4-1-u4-X01","explanation":["⑤를 떠올려요.","넣기 어려운 카드가 있었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 카드를 모두 섞은 뒤 두 사람이 세 장씩 나누어 가졌다.","② 카드를 한 장씩 보여 주며 생물의 이름을 말했다.","③ 같은 카드면 가져오고, 아니면 가운데 카드를 한 장 가져왔다.","④ 모은 카드를 동물, 식물, 그 밖의 생물로 나누었다.","⑤ 표고버섯, 곰팡이, 해캄은 어디에도 넣기 어려웠다."],"title":"생물 놀이 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#7','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C2',3,'mc','auto','거북과 소나무를 나눌 때 쓴 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C2","difficulty":3,"kind":"mc","stem":"거북과 소나무를 나눌 때 쓴 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"스스로 움직이는지, 뿌리·줄기·잎이 있는지","correct":true},{"t":"색깔이 무엇인지","mis":"SC4-1-u4-X04"},{"t":"크기가 얼마나 큰지","mis":"SC4-1-u4-X04"},{"t":"이름이 몇 글자인지","mis":"SC4-1-u4-X04"}],"explanation":["동물과 식물의 특징이에요.","두 가지 기준이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#8','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C4',4,'mc','auto','친구가 「표고버섯은 나무에 붙어 자라고 움직이지 않으니 식물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X02','SC4-1-u4-X04']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C4","difficulty":4,"kind":"mc","stem":"친구가 「표고버섯은 나무에 붙어 자라고 움직이지 않으니 식물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「움직이지 않아도 뿌리·줄기·잎이 없으면 식물이라고 하기 어려워.」","correct":true},{"t":"「맞아, 움직이지 않으면 모두 식물이야.」","mis":"SC4-1-u4-X02"},{"t":"「갈색이라서 식물이 아니야.」","mis":"SC4-1-u4-X04"},{"t":"「크기가 작아서 식물이 아니야.」","mis":"SC4-1-u4-X04"}],"explanation":["움직임만 보면 안 돼요.","뿌리·줄기·잎이 있나요?","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#9','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C6',4,'mc','auto','친구가 「그 밖의 생물은 깊은 숲이나 바닷속에만 있어서 우리 집에는 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X05','SC4-1-u4-X01','SC4-1-u4-X02']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C6","difficulty":4,"kind":"mc","stem":"친구가 「그 밖의 생물은 깊은 숲이나 바닷속에만 있어서 우리 집에는 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「오래 둔 빵에 핀 곰팡이처럼 우리 집에도 살고 있어.」","correct":true},{"t":"「맞아, 우리 집에는 없어.」","mis":"SC4-1-u4-X05"},{"t":"「그 밖의 생물은 살아 있지 않아.」","mis":"SC4-1-u4-X01"},{"t":"「그 밖의 생물은 모두 식물이야.」","mis":"SC4-1-u4-X02"}],"explanation":["집 안을 떠올려요.","빵에 핀 것이 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L01_challenge#10','sci',4,1,'u4','L01','g4_1_sci_u4_L01_challenge','lesson_challenge','SC4-1-u4-C3',4,'essay','teacher','버섯, 해캄, 강아지, 소나무 카드를 동물, 식물, 그 밖의 생물로 나누고, 버섯과 해캄을 그 밖의 생물로 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C3","difficulty":4,"kind":"essay","stem":"버섯, 해캄, 강아지, 소나무 카드를 동물, 식물, 그 밖의 생물로 나누고, 버섯과 해캄을 그 밖의 생물로 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 강아지는 동물, 소나무는 식물, 버섯과 해캄은 그 밖의 생물이다. 버섯은 움직이지 않지만 뿌리·줄기·잎이 없고, 해캄은 초록색이지만 뿌리·줄기·잎이 없어 동물에도 식물에도 넣기 어렵기 때문이다.","scoring_points":["네 카드를 바르게 나누었는가","버섯을 그 밖의 생물로 나눈 까닭을 썼는가","해캄을 그 밖의 생물로 나눈 까닭을 썼는가"]},"explanation":["기준 두 가지를 떠올려요.","하나씩 따져요.","까닭을 써요."],"asset":{"type":"passage","lines":["① 카드를 모두 섞은 뒤 두 사람이 세 장씩 나누어 가졌다.","② 카드를 한 장씩 보여 주며 생물의 이름을 말했다.","③ 같은 카드면 가져오고, 아니면 가운데 카드를 한 장 가져왔다.","④ 모은 카드를 동물, 식물, 그 밖의 생물로 나누었다.","⑤ 표고버섯, 곰팡이, 해캄은 어디에도 넣기 어려웠다."],"title":"생물 놀이 카드 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#1','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C12',1,'mc','auto','버섯과 곰팡이 같은 생물을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X02','SC4-1-u4-X04','SC4-1-u4-X07']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C12","difficulty":1,"kind":"mc","stem":"버섯과 곰팡이 같은 생물을 무엇이라고 하나요?","options":[{"t":"균류","correct":true},{"t":"식물","mis":"SC4-1-u4-X02"},{"t":"동물","mis":"SC4-1-u4-X04"},{"t":"흙","mis":"SC4-1-u4-X07"}],"explanation":["오늘 배운 이름이에요.","균사로 되어 있어요.","균류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#2','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C10',1,'mc','auto','균류는 자손을 남기기 위해 무엇을 만드나요?',ARRAY['SC4-1-u4-X09']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C10","difficulty":1,"kind":"mc","stem":"균류는 자손을 남기기 위해 무엇을 만드나요?","options":[{"t":"포자","correct":true},{"t":"씨","mis":"SC4-1-u4-X09"},{"t":"알","mis":"SC4-1-u4-X09"},{"t":"꽃","mis":"SC4-1-u4-X09"}],"explanation":["씨가 아니에요.","아주 작은 것이에요.","포자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#3','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C13',1,'ox','auto','버섯과 곰팡이는 습기가 많고 따뜻한 곳에서 잘 자라요.',ARRAY['SC4-1-u4-X11']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C13","difficulty":1,"kind":"ox","stem":"버섯과 곰팡이는 습기가 많고 따뜻한 곳에서 잘 자라요.","answer":"O","reason_options":[{"t":"균류는 습기가 많고 그늘지며 따뜻한 곳에서 잘 자라기 때문에","correct":true},{"t":"균류는 바짝 마른 곳을 좋아하기 때문에","mis":"SC4-1-u4-X11"}],"mis":"SC4-1-u4-X11","explanation":["여름 장마철을 떠올려요.","축축해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#4','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C9',1,'sa','auto','버섯과 곰팡이를 이루는 가늘고 긴 실 모양의 부분을 무엇이라고 하나요?','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C9","difficulty":1,"kind":"sa","stem":"버섯과 곰팡이를 이루는 가늘고 긴 실 모양의 부분을 무엇이라고 하나요?","answer":["균사"],"explanation":["③을 떠올려요.","실 모양이에요.","균사예요."],"mis":"SC4-1-u4-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#5','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C7',2,'match','auto','맨눈으로 관찰한 곳과 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C7","difficulty":2,"kind":"match","stem":"맨눈으로 관찰한 곳과 모습을 알맞게 이으세요.","pairs":[{"l":"버섯의 갓","r":"우산 모양"},{"l":"버섯의 자루","r":"기다란 기둥 모양"},{"l":"곰팡이","r":"하얗고 푸른 솜털 모양"}],"mis":"SC4-1-u4-X12","explanation":["①을 읽어요.","곳마다 모양이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 맨눈 — 버섯은 갓과 자루가 보이고, 곰팡이는 솜털 같았다.","② 돋보기 — 버섯 갓 안쪽에 얇은 주름이 보였다.","③ 현미경 — 가늘고 긴 실 모양이 얽혀 있었다.","④ 곰팡이 실 끝에 작은 알갱이가 달려 있었다."],"title":"버섯과 곰팡이 확대 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#6','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C11',2,'mc','auto','균류는 필요한 양분을 어떻게 얻나요?',ARRAY['SC4-1-u4-X10','SC4-1-u4-X07']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C11","difficulty":2,"kind":"mc","stem":"균류는 필요한 양분을 어떻게 얻나요?","options":[{"t":"죽은 생물이나 다른 생물에서 얻는다","correct":true},{"t":"스스로 만든다","mis":"SC4-1-u4-X10"},{"t":"햇빛만 받으면 생긴다","mis":"SC4-1-u4-X10"},{"t":"양분이 전혀 필요 없다","mis":"SC4-1-u4-X07"}],"explanation":["스스로 만들지 못해요.","다른 데서 얻어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#7','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C14',2,'ox','auto','오래 둔 빵에 핀 곰팡이는 아무것도 없던 곳에서 저절로 생겨요.',ARRAY['SC4-1-u4-X08']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C14","difficulty":2,"kind":"ox","stem":"오래 둔 빵에 핀 곰팡이는 아무것도 없던 곳에서 저절로 생겨요.","answer":"X","reason_options":[{"t":"눈에 보이지 않던 포자가 빵에 내려앉아 자랐기 때문에","correct":true},{"t":"빵이 스스로 곰팡이로 변하기 때문에","mis":"SC4-1-u4-X08"}],"mis":"SC4-1-u4-X08","explanation":["포자는 아주 작아요.","공기 중에 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#8','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C15',2,'mc','auto','버섯과 곰팡이를 관찰할 때 지킬 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X14']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C15","difficulty":2,"kind":"mc","stem":"버섯과 곰팡이를 관찰할 때 지킬 일로 알맞은 것은 무엇인가요?","options":[{"t":"마스크와 장갑을 끼고 관찰한다","correct":true},{"t":"얼굴을 가까이 대고 냄새를 맡는다","mis":"SC4-1-u4-X14"},{"t":"관찰한 버섯을 맛본다","mis":"SC4-1-u4-X14"},{"t":"맨손으로 곰팡이를 만진다","mis":"SC4-1-u4-X14"}],"explanation":["몸을 지켜요.","맨손·맨얼굴은 안 돼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#9','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C8',2,'mc','auto','버섯과 곰팡이를 관찰하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X13']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C8","difficulty":2,"kind":"mc","stem":"버섯과 곰팡이를 관찰하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"맨눈 → 돋보기 → 현미경","correct":true},{"t":"현미경 → 돋보기 → 맨눈","mis":"SC4-1-u4-X13"},{"t":"맨눈으로만 보고 끝낸다","mis":"SC4-1-u4-X13"},{"t":"돋보기 → 맨눈 → 현미경","mis":"SC4-1-u4-X13"}],"explanation":["점점 크게 봐요.","①부터 차례대로요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 맨눈 — 버섯은 갓과 자루가 보이고, 곰팡이는 솜털 같았다.","② 돋보기 — 버섯 갓 안쪽에 얇은 주름이 보였다.","③ 현미경 — 가늘고 긴 실 모양이 얽혀 있었다.","④ 곰팡이 실 끝에 작은 알갱이가 달려 있었다."],"title":"버섯과 곰팡이 확대 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_basic#10','sci',4,1,'u4','L02','g4_1_sci_u4_L02_basic','lesson_basic','SC4-1-u4-C13',3,'mc','auto','버섯과 곰팡이가 여름철에 특히 많이 보이는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X11','SC4-1-u4-X08','SC4-1-u4-X09']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C13","difficulty":3,"kind":"mc","stem":"버섯과 곰팡이가 여름철에 특히 많이 보이는 까닭은 무엇인가요?","options":[{"t":"여름은 따뜻하고 습기가 많기 때문에","correct":true},{"t":"여름은 바짝 마르고 햇빛이 강하기 때문에","mis":"SC4-1-u4-X11"},{"t":"여름에는 곰팡이가 저절로 생기기 때문에","mis":"SC4-1-u4-X08"},{"t":"여름에는 버섯이 씨를 많이 뿌리기 때문에","mis":"SC4-1-u4-X09"}],"explanation":["여름 날씨를 떠올려요.","덥고 축축해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
