INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#3','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C14',3,'error','auto','빵에 핀 곰팡이를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X08','SC4-1-u4-X11']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C14","difficulty":3,"kind":"error","stem":"빵에 핀 곰팡이를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「곰팡이는 빵 속에서 저절로 생겨났어.」","correct":true,"mis_target":"SC4-1-u4-X08"},{"t":"친구 가 — 「눈에 안 보이는 포자가 빵에 내려앉았을 거야.」","mis":"SC4-1-u4-X08"},{"t":"친구 나 — 「빵이 따뜻하고 축축해서 곰팡이가 잘 자랐어.」","mis":"SC4-1-u4-X11"}],"explanation":["포자를 떠올려요.","저절로 생기지 않아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
