INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#6','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C7',3,'ox','auto','버섯의 자루는 식물의 줄기와 같은 것이에요.',ARRAY['SC4-1-u4-X02']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C7","difficulty":3,"kind":"ox","stem":"버섯의 자루는 식물의 줄기와 같은 것이에요.","answer":"X","reason_options":[{"t":"비슷해 보여도 버섯은 균사로 되어 있어 식물의 줄기와 다르기 때문에","correct":true},{"t":"모양이 비슷하면 같은 것이기 때문에","mis":"SC4-1-u4-X02"}],"mis":"SC4-1-u4-X02","explanation":["생김새만 보면 안 돼요.","균사로 되어 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#7','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C15',3,'mc','auto','관찰이 끝난 버섯과 곰팡이를 다루는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X14']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C15","difficulty":3,"kind":"mc","stem":"관찰이 끝난 버섯과 곰팡이를 다루는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"먹지 않고 선생님께 드린 뒤 손을 깨끗이 씻는다","correct":true},{"t":"버섯은 깨끗해 보이니 먹어 본다","mis":"SC4-1-u4-X14"},{"t":"남은 곰팡이 빵을 가방에 넣어 둔다","mis":"SC4-1-u4-X14"},{"t":"손을 씻지 않고 간식을 먹는다","mis":"SC4-1-u4-X14"}],"explanation":["먹으면 안 돼요.","손도 씻어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#8','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C12',4,'mc','auto','친구가 「곰팡이는 하얀 솜털이나 먼지일 뿐 살아 있는 생물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X07','SC4-1-u4-X08','SC4-1-u4-X02']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C12","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이는 하얀 솜털이나 먼지일 뿐 살아 있는 생물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「확대해 보면 균사가 있고 포자로 번식하니 곰팡이도 생물이야.」","correct":true},{"t":"「맞아, 곰팡이는 먼지야.」","mis":"SC4-1-u4-X07"},{"t":"「곰팡이는 빵이 변한 거야.」","mis":"SC4-1-u4-X08"},{"t":"「곰팡이는 식물이야.」","mis":"SC4-1-u4-X02"}],"explanation":["확대해 본 모습을 떠올려요.","균사와 포자가 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#9','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C11',4,'mc','auto','친구가 「곰팡이도 식물처럼 스스로 양분을 만들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X10','SC4-1-u4-X07','SC4-1-u4-X09']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C11","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이도 식물처럼 스스로 양분을 만들어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「균류는 양분을 스스로 만들지 못하고 죽은 생물이나 다른 생물에서 얻어.」","correct":true},{"t":"「맞아, 햇빛으로 양분을 만들어.」","mis":"SC4-1-u4-X10"},{"t":"「곰팡이는 양분이 전혀 필요 없어.」","mis":"SC4-1-u4-X07"},{"t":"「곰팡이는 씨에서 양분을 얻어.」","mis":"SC4-1-u4-X09"}],"explanation":["빵에 핀 곰팡이를 떠올려요.","빵에서 얻어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L02_challenge#10','sci',4,1,'u4','L02','g4_1_sci_u4_L02_challenge','lesson_challenge','SC4-1-u4-C13',4,'essay','teacher','빵 두 조각 가운데 하나는 따뜻하고 축축한 곳에, 하나는 바짝 마른 곳에 두었어요. 어느 빵에 곰팡이가 더 잘 필지 쓰고, 그 까닭을 균류가 잘 자라는 곳과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C13","difficulty":4,"kind":"essay","stem":"빵 두 조각 가운데 하나는 따뜻하고 축축한 곳에, 하나는 바짝 마른 곳에 두었어요. 어느 빵에 곰팡이가 더 잘 필지 쓰고, 그 까닭을 균류가 잘 자라는 곳과 이어 쓰세요.","answer_guide":{"answer":"예: 따뜻하고 축축한 곳에 둔 빵에 곰팡이가 더 잘 핀다. 공기 중에 있던 포자가 빵에 내려앉고, 균류는 습기가 많고 그늘지며 따뜻한 곳에서 잘 자라기 때문이다.","scoring_points":["따뜻하고 축축한 곳의 빵을 골랐는가","균류가 잘 자라는 곳을 썼는가","포자에서 자란다는 것을 이었는가"]},"explanation":["균류가 좋아하는 곳이에요.","포자도 떠올려요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#1','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C19',1,'mc','auto','해캄과 짚신벌레 같은 생물을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X18','SC4-1-u4-X03','SC4-1-u4-X15']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C19","difficulty":1,"kind":"mc","stem":"해캄과 짚신벌레 같은 생물을 무엇이라고 하나요?","options":[{"t":"원생생물","correct":true},{"t":"균류","mis":"SC4-1-u4-X18"},{"t":"식물","mis":"SC4-1-u4-X03"},{"t":"동물","mis":"SC4-1-u4-X15"}],"explanation":["오늘 배운 이름이에요.","어디에도 속하지 않아요.","원생생물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#2','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C17',1,'mc','auto','짚신벌레의 생김새로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X18','SC4-1-u4-X03']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C17","difficulty":1,"kind":"mc","stem":"짚신벌레의 생김새로 알맞은 것은 무엇인가요?","options":[{"t":"짚신처럼 길쭉하고 끝이 둥글다","correct":true},{"t":"가늘고 긴 머리카락 모양이다","mis":"SC4-1-u4-X17"},{"t":"우산 모양 갓이 있다","mis":"SC4-1-u4-X18"},{"t":"뿌리·줄기·잎이 있다","mis":"SC4-1-u4-X03"}],"explanation":["이름을 떠올려요.","짚신 모양이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#3','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C20',1,'ox','auto','원생생물은 주로 연못이나 논처럼 물이 고인 곳에서 살아요.',ARRAY['SC4-1-u4-X16']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C20","difficulty":1,"kind":"ox","stem":"원생생물은 주로 연못이나 논처럼 물이 고인 곳에서 살아요.","answer":"O","reason_options":[{"t":"원생생물은 물살이 느리거나 물이 고인 곳에서 주로 살기 때문에","correct":true},{"t":"원생생물은 메마른 모래밭에서 주로 살기 때문에","mis":"SC4-1-u4-X16"}],"mis":"SC4-1-u4-X16","explanation":["연못 물에서 떠 왔어요.","물에서 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#4','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C16',1,'sa','auto','해캄은 무슨 색인가요? 한 낱말로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C16","difficulty":1,"kind":"sa","stem":"해캄은 무슨 색인가요? 한 낱말로 쓰세요.","answer":["초록색","초록","녹색","초록빛"],"explanation":["㉮를 읽어요.","풀잎 같은 색이에요.","초록색이에요."],"mis":"SC4-1-u4-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#5','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C18',2,'match','auto','생물과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C18","difficulty":2,"kind":"match","stem":"생물과 특징을 알맞게 이으세요.","pairs":[{"l":"해캄","r":"스스로 양분을 만든다"},{"l":"짚신벌레","r":"스스로 움직인다"},{"l":"곰팡이","r":"균사로 되어 있다"}],"mis":"SC4-1-u4-X17","explanation":["하나씩 떠올려요.","곰팡이는 균류예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#6','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C19',2,'mc','auto','원생생물에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X18','SC4-1-u4-X03','SC4-1-u4-X16']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C19","difficulty":2,"kind":"mc","stem":"원생생물에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"동물·식물과 비교하면 생김새가 단순하다","correct":true},{"t":"균사로 이루어져 있다","mis":"SC4-1-u4-X18"},{"t":"뿌리·줄기·잎이 발달했다","mis":"SC4-1-u4-X03"},{"t":"모두 메마른 땅에서만 산다","mis":"SC4-1-u4-X16"}],"explanation":["생김새를 떠올려요.","단순해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#7','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C22',2,'ox','auto','해캄은 스스로 양분을 만드니까 식물이에요.',ARRAY['SC4-1-u4-X03']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C22","difficulty":2,"kind":"ox","stem":"해캄은 스스로 양분을 만드니까 식물이에요.","answer":"X","reason_options":[{"t":"양분을 만들어도 뿌리·줄기·잎이 없어 식물이라고 하기 어렵기 때문에","correct":true},{"t":"스스로 양분을 만드는 생물은 모두 식물이기 때문에","mis":"SC4-1-u4-X03"}],"mis":"SC4-1-u4-X03","explanation":["뿌리·줄기·잎이 있나요?","없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#8','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C17',2,'mc','auto','짚신벌레가 물속에서 헤엄칠 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X03','SC4-1-u4-X18']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C17","difficulty":2,"kind":"mc","stem":"짚신벌레가 물속에서 헤엄칠 수 있는 까닭은 무엇인가요?","options":[{"t":"몸 겉의 가는 털을 움직이기 때문에","correct":true},{"t":"지느러미가 있기 때문에","mis":"SC4-1-u4-X17"},{"t":"뿌리로 물을 밀기 때문에","mis":"SC4-1-u4-X03"},{"t":"균사를 길게 뻗기 때문에","mis":"SC4-1-u4-X18"}],"explanation":["㉯를 읽어요.","가는 털이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉮ 가늘고 긴 머리카락 모양이고 초록색이며 미끌미끌하다.","㉮ 현미경 — 작고 둥근 초록색 알갱이가 띠 모양으로 이어졌다.","㉯ 짚신처럼 길쭉하고 끝이 둥글다.","㉯ 현미경 — 몸 겉의 가는 털을 움직여 헤엄쳤다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다."],"title":"연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#9','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C20',2,'mc','auto','바다에 사는 원생생물은 무엇인가요?',ARRAY['SC4-1-u4-X16','SC4-1-u4-X15','SC4-1-u4-X03']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C20","difficulty":2,"kind":"mc","stem":"바다에 사는 원생생물은 무엇인가요?","options":[{"t":"미역","correct":true},{"t":"짚신벌레","mis":"SC4-1-u4-X16"},{"t":"표고버섯","mis":"SC4-1-u4-X15"},{"t":"소나무","mis":"SC4-1-u4-X03"}],"explanation":["바닷속을 떠올려요.","다시마와 비슷해요.","미역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_basic#10','sci',4,1,'u4','L03','g4_1_sci_u4_L03_basic','lesson_basic','SC4-1-u4-C21',3,'mc','auto','원생생물의 공통점을 찾을 때 생김새와 함께 사는 곳을 살펴보는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X19','SC4-1-u4-X16','SC4-1-u4-X20']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C21","difficulty":3,"kind":"mc","stem":"원생생물의 공통점을 찾을 때 생김새와 함께 사는 곳을 살펴보는 까닭은 무엇인가요?","options":[{"t":"종류가 아주 많아 생김새가 서로 많이 다르기 때문에","correct":true},{"t":"원생생물은 모두 생김새가 똑같기 때문에","mis":"SC4-1-u4-X19"},{"t":"원생생물은 사는 곳이 없기 때문에","mis":"SC4-1-u4-X16"},{"t":"원생생물은 살아 있지 않기 때문에","mis":"SC4-1-u4-X20"}],"explanation":["해캄과 짚신벌레를 견줘요.","많이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#1','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C16',2,'blank','auto','「해캄을 현미경으로 보면 작고 둥근 초록색 (      )이 띠 모양으로 이어져 있어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X18','SC4-1-u4-X12','SC4-1-u4-X17']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C16","difficulty":2,"kind":"blank","stem":"「해캄을 현미경으로 보면 작고 둥근 초록색 (      )이 띠 모양으로 이어져 있어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"알갱이","correct":true},{"t":"균사","mis":"SC4-1-u4-X18"},{"t":"포자","mis":"SC4-1-u4-X12"},{"t":"털","mis":"SC4-1-u4-X17"}],"explanation":["㉮의 현미경 모습이에요.","작고 둥글어요.","「알갱이」예요."],"asset":{"type":"passage","lines":["㉮ 가늘고 긴 머리카락 모양이고 초록색이며 미끌미끌하다.","㉮ 현미경 — 작고 둥근 초록색 알갱이가 띠 모양으로 이어졌다.","㉯ 짚신처럼 길쭉하고 끝이 둥글다.","㉯ 현미경 — 몸 겉의 가는 털을 움직여 헤엄쳤다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다."],"title":"연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#2','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C23',2,'mc','auto','해캄과 짚신벌레를 관찰할 때의 마음가짐으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X20']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C23","difficulty":2,"kind":"mc","stem":"해캄과 짚신벌레를 관찰할 때의 마음가짐으로 알맞은 것은 무엇인가요?","options":[{"t":"작은 생물도 생명이 있으니 조심스럽게 다룬다","correct":true},{"t":"너무 작으니 함부로 다뤄도 된다","mis":"SC4-1-u4-X20"},{"t":"생물이 아니니 마음대로 버린다","mis":"SC4-1-u4-X20"},{"t":"관찰한 뒤 손을 씻지 않는다","mis":"SC4-1-u4-X20"}],"explanation":["작아도 살아 있어요.","소중히 다뤄요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#3','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C19',3,'error','auto','원생생물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X15','SC4-1-u4-X19']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C19","difficulty":3,"kind":"error","stem":"원생생물에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「짚신벌레는 움직이니까 동물이야.」","correct":true,"mis_target":"SC4-1-u4-X15"},{"t":"친구 나 — 「원생생물은 동물·식물·균류 어디에도 속하지 않아.」","mis":"SC4-1-u4-X15"},{"t":"친구 다 — 「해캄과 짚신벌레는 생김새가 단순해.」","mis":"SC4-1-u4-X19"}],"explanation":["원생생물의 뜻을 떠올려요.","동물에도 속하지 않아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#4','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C21',3,'mc','auto','연못 물에서 관찰할 수 있는 원생생물끼리 모은 것은 무엇인가요?',ARRAY['SC4-1-u4-X18','SC4-1-u4-X15','SC4-1-u4-X03']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C21","difficulty":3,"kind":"mc","stem":"연못 물에서 관찰할 수 있는 원생생물끼리 모은 것은 무엇인가요?","options":[{"t":"아메바, 나팔벌레, 짚신벌레","correct":true},{"t":"아메바, 곰팡이, 표고버섯","mis":"SC4-1-u4-X18"},{"t":"붕어, 다슬기, 개구리","mis":"SC4-1-u4-X15"},{"t":"나팔벌레, 소나무, 해바라기","mis":"SC4-1-u4-X03"}],"explanation":["하나씩 따져요.","버섯·물고기·나무는 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#5','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C18',3,'mc','auto','해캄과 짚신벌레를 견줄 때 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X18','SC4-1-u4-X16']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C18","difficulty":3,"kind":"mc","stem":"해캄과 짚신벌레를 견줄 때 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"해캄은 스스로 양분을 만들고, 짚신벌레는 스스로 움직인다","correct":true},{"t":"해캄은 스스로 움직이고, 짚신벌레는 스스로 양분을 만든다","mis":"SC4-1-u4-X17"},{"t":"둘 다 균사로 되어 있다","mis":"SC4-1-u4-X18"},{"t":"해캄은 땅 위에, 짚신벌레는 하늘에 산다","mis":"SC4-1-u4-X16"}],"explanation":["둘의 특징을 떠올려요.","양분과 움직임이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#6','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C20',3,'ox','auto','미역과 다시마처럼 바다에 사는 원생생물도 있어요.',ARRAY['SC4-1-u4-X16']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C20","difficulty":3,"kind":"ox","stem":"미역과 다시마처럼 바다에 사는 원생생물도 있어요.","answer":"O","reason_options":[{"t":"원생생물은 주로 물에서 살고 바다에 사는 것도 있기 때문에","correct":true},{"t":"원생생물은 연못에만 살고 바다에는 없기 때문에","mis":"SC4-1-u4-X16"}],"mis":"SC4-1-u4-X16","explanation":["사는 곳을 떠올려요.","바다도 물이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#7','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C22',3,'mc','auto','해캄을 식물로 나누지 않는 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u4-X03','SC4-1-u4-X17','SC4-1-u4-X18']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C22","difficulty":3,"kind":"mc","stem":"해캄을 식물로 나누지 않는 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"해캄은 뿌리·줄기·잎이 발달하지 않았기 때문에","correct":true},{"t":"해캄은 초록색이 아니기 때문에","mis":"SC4-1-u4-X03"},{"t":"해캄은 스스로 양분을 만들지 못하기 때문에","mis":"SC4-1-u4-X17"},{"t":"해캄은 균사로 되어 있기 때문에","mis":"SC4-1-u4-X18"}],"explanation":["해캄은 초록색이에요.","그래도 식물이 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#8','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C22',4,'mc','auto','친구가 「해캄은 초록색이고 스스로 양분도 만드니까 식물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X03','SC4-1-u4-X04']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C22","difficulty":4,"kind":"mc","stem":"친구가 「해캄은 초록색이고 스스로 양분도 만드니까 식물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「양분을 만들어도 뿌리·줄기·잎이 없어서 식물이라고 하기 어려워.」","correct":true},{"t":"「맞아, 초록색이면 모두 식물이야.」","mis":"SC4-1-u4-X03"},{"t":"「물에 살아서 식물이 아니야.」","mis":"SC4-1-u4-X04"},{"t":"「크기가 작아서 식물이 아니야.」","mis":"SC4-1-u4-X04"}],"explanation":["색깔은 기준이 아니에요.","뿌리·줄기·잎을 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#9','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C23',4,'mc','auto','친구가 「짚신벌레는 너무 작아서 살아 있는 생물이 아닐 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X20','SC4-1-u4-X18','SC4-1-u4-X03']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C23","difficulty":4,"kind":"mc","stem":"친구가 「짚신벌레는 너무 작아서 살아 있는 생물이 아닐 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「작고 단순해도 스스로 움직이며 살아가는 생물이야.」","correct":true},{"t":"「맞아, 작으면 생물이 아니야.」","mis":"SC4-1-u4-X20"},{"t":"「짚신벌레는 균류야.」","mis":"SC4-1-u4-X18"},{"t":"「짚신벌레는 식물이야.」","mis":"SC4-1-u4-X03"}],"explanation":["㉯를 떠올려요.","헤엄쳤어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L03_challenge#10','sci',4,1,'u4','L03','g4_1_sci_u4_L03_challenge','lesson_challenge','SC4-1-u4-C19',4,'essay','teacher','「연못 물 관찰」을 보고 ㉮와 ㉯의 다른 점과 공통점을 하나씩 쓰고, 이 생물들이 주로 사는 곳을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C19","difficulty":4,"kind":"essay","stem":"「연못 물 관찰」을 보고 ㉮와 ㉯의 다른 점과 공통점을 하나씩 쓰고, 이 생물들이 주로 사는 곳을 쓰세요.","answer_guide":{"answer":"예: ㉮ 해캄은 스스로 양분을 만들고 ㉯ 짚신벌레는 스스로 움직인다는 점이 다르다. 둘 다 동물·식물보다 생김새가 단순하고 동물·식물·균류에 속하지 않는 원생생물이다. 주로 물살이 느리거나 물이 고인 연못·논·하천에 산다.","scoring_points":["다른 점을 하나 썼는가","공통점(원생생물)을 썼는가","사는 곳을 썼는가"]},"explanation":["㉮와 ㉯를 견줘요.","같은 점도 찾아요.","사는 곳도 써요."],"asset":{"type":"passage","lines":["㉮ 가늘고 긴 머리카락 모양이고 초록색이며 미끌미끌하다.","㉮ 현미경 — 작고 둥근 초록색 알갱이가 띠 모양으로 이어졌다.","㉯ 짚신처럼 길쭉하고 끝이 둥글다.","㉯ 현미경 — 몸 겉의 가는 털을 움직여 헤엄쳤다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다."],"title":"연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#1','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C24',1,'mc','auto','젖산균과 대장균 같은 생물을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X26','SC4-1-u4-X21']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C24","difficulty":1,"kind":"mc","stem":"젖산균과 대장균 같은 생물을 무엇이라고 하나요?","options":[{"t":"세균","correct":true},{"t":"균류","mis":"SC4-1-u4-X26"},{"t":"원생생물","mis":"SC4-1-u4-X26"},{"t":"식물","mis":"SC4-1-u4-X21"}],"explanation":["오늘 배운 이름이에요.","아주 작아요.","세균이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#2','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C25',1,'mc','auto','세균의 모양이 아닌 것은 무엇인가요?',ARRAY['SC4-1-u4-X24']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C25","difficulty":1,"kind":"mc","stem":"세균의 모양이 아닌 것은 무엇인가요?","options":[{"t":"가늘고 긴 실이 이어진 모양","correct":true},{"t":"공 모양","mis":"SC4-1-u4-X24"},{"t":"막대 모양","mis":"SC4-1-u4-X24"},{"t":"나선 모양","mis":"SC4-1-u4-X24"}],"explanation":["그림을 떠올려요.","실 모양은 다른 생물이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 공 모양 — 여러 개가 이어져 포도송이처럼 보인다.","② 막대 모양 — 길쭉한 막대가 나란히 붙어 있다.","③ 나선 모양 — 용수철처럼 배배 꼬여 있다.","④ 꼬리 달린 나선 모양 — 가는 꼬리가 달려 있다."],"title":"크게 확대한 세균 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#3','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C26',1,'ox','auto','세균은 크기가 매우 작아 맨눈으로 볼 수 없어요.',ARRAY['SC4-1-u4-X23']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C26","difficulty":1,"kind":"ox","stem":"세균은 크기가 매우 작아 맨눈으로 볼 수 없어요.","answer":"O","reason_options":[{"t":"세균은 균류나 원생생물보다도 작기 때문에","correct":true},{"t":"세균은 버섯보다 커서 쉽게 보이기 때문에","mis":"SC4-1-u4-X23"}],"mis":"SC4-1-u4-X23","explanation":["크게 확대해야 보여요.","아주 작아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#4','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C25',1,'sa','auto','대장균은 어떤 모양인가요? 「○○ 모양」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C25","difficulty":1,"kind":"sa","stem":"대장균은 어떤 모양인가요? 「○○ 모양」의 ○○에 알맞은 말을 쓰세요.","answer":["막대"],"explanation":["②를 떠올려요.","길쭉해요.","막대예요."],"mis":"SC4-1-u4-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#5','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C25',2,'match','auto','세균과 모양을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C25","difficulty":2,"kind":"match","stem":"세균과 모양을 알맞게 이으세요.","pairs":[{"l":"포도상구균","r":"공 모양"},{"l":"대장균","r":"막대 모양"},{"l":"콜레라균","r":"나선 모양"}],"mis":"SC4-1-u4-X24","explanation":["그림을 떠올려요.","이름과 모양이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 공 모양 — 여러 개가 이어져 포도송이처럼 보인다.","② 막대 모양 — 길쭉한 막대가 나란히 붙어 있다.","③ 나선 모양 — 용수철처럼 배배 꼬여 있다.","④ 꼬리 달린 나선 모양 — 가는 꼬리가 달려 있다."],"title":"크게 확대한 세균 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#6','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C27',2,'mc','auto','세균이 사는 곳으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X22','SC4-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C27","difficulty":2,"kind":"mc","stem":"세균이 사는 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"땅, 물, 다른 생물의 몸, 우리가 쓰는 물건 등 어디에나","correct":true},{"t":"더러운 쓰레기통 속에만","mis":"SC4-1-u4-X22"},{"t":"아주 먼 바닷속에만","mis":"SC4-1-u4-X22"},{"t":"세균은 사는 곳이 없다","mis":"SC4-1-u4-X21"}],"explanation":["사는 곳 네 군데를 떠올려요.","어디에나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#7','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C28',2,'ox','auto','세균은 눈에 보이지 않으니 생물이 아니에요.',ARRAY['SC4-1-u4-X21']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C28","difficulty":2,"kind":"ox","stem":"세균은 눈에 보이지 않으니 생물이 아니에요.","answer":"X","reason_options":[{"t":"세균도 양분이 필요하고 수가 늘어나는 생물이기 때문에","correct":true},{"t":"눈에 보이지 않는 것은 살아 있지 않기 때문에","mis":"SC4-1-u4-X21"}],"mis":"SC4-1-u4-X21","explanation":["생물의 특징을 떠올려요.","양분이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#8','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C29',2,'mc','auto','세균이 짧은 시간에 많은 수로 늘어날 수 있는 때는 언제인가요?',ARRAY['SC4-1-u4-X25','SC4-1-u4-X21']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C29","difficulty":2,"kind":"mc","stem":"세균이 짧은 시간에 많은 수로 늘어날 수 있는 때는 언제인가요?","options":[{"t":"살기에 좋은 조건이 되었을 때","correct":true},{"t":"꽁꽁 얼었을 때만","mis":"SC4-1-u4-X25"},{"t":"조건과 상관없이 언제나 똑같이","mis":"SC4-1-u4-X25"},{"t":"세균은 수가 늘지 않는다","mis":"SC4-1-u4-X21"}],"explanation":["따뜻하면 어떨까요?","살기 좋아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#9','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C25',2,'mc','auto','헬리코박터 파일로리의 모양으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X24','SC4-1-u4-X26']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C25","difficulty":2,"kind":"mc","stem":"헬리코박터 파일로리의 모양으로 알맞은 것은 무엇인가요?","options":[{"t":"나선 모양에 가는 꼬리가 달려 있다","correct":true},{"t":"공 모양이 포도송이처럼 붙어 있다","mis":"SC4-1-u4-X24"},{"t":"가늘고 긴 실 모양이다","mis":"SC4-1-u4-X24"},{"t":"우산 모양 갓이 있다","mis":"SC4-1-u4-X26"}],"explanation":["④를 읽어요.","꼬리가 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 공 모양 — 여러 개가 이어져 포도송이처럼 보인다.","② 막대 모양 — 길쭉한 막대가 나란히 붙어 있다.","③ 나선 모양 — 용수철처럼 배배 꼬여 있다.","④ 꼬리 달린 나선 모양 — 가는 꼬리가 달려 있다."],"title":"크게 확대한 세균 그림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_basic#10','sci',4,1,'u4','L04','g4_1_sci_u4_L04_basic','lesson_basic','SC4-1-u4-C29',3,'mc','auto','냉장고 밖에 둔 우유가 냉장고 안에 둔 우유보다 빨리 상하는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X25']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C29","difficulty":3,"kind":"mc","stem":"냉장고 밖에 둔 우유가 냉장고 안에 둔 우유보다 빨리 상하는 까닭은 무엇인가요?","options":[{"t":"밖은 온도가 높아 세균이 살기 좋은 조건이 되기 때문에","correct":true},{"t":"냉장고 안에는 세균이 아예 없기 때문에","mis":"SC4-1-u4-X25"},{"t":"밖이 밝아 우유가 빛을 받기 때문에","mis":"SC4-1-u4-X25"},{"t":"우유갑이 밖에서 더 빨리 낡기 때문에","mis":"SC4-1-u4-X25"}],"explanation":["온도를 견줘요.","따뜻하면 빨리 늘어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#1','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C26',2,'blank','auto','「세균은 균류나 원생생물보다 크기가 (      ).」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X23']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C26","difficulty":2,"kind":"blank","stem":"「세균은 균류나 원생생물보다 크기가 (      ).」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"작아요","correct":true},{"t":"커요","mis":"SC4-1-u4-X23"},{"t":"똑같아요","mis":"SC4-1-u4-X23"},{"t":"훨씬 커서 맨눈으로 보여요","mis":"SC4-1-u4-X23"}],"explanation":["맨눈으로 볼 수 있나요?","아니에요.","「작아요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#2','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C26',2,'mc','auto','세균을 관찰할 때 크게 확대한 그림이나 사진을 쓰는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X23','SC4-1-u4-X21']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C26","difficulty":2,"kind":"mc","stem":"세균을 관찰할 때 크게 확대한 그림이나 사진을 쓰는 까닭은 무엇인가요?","options":[{"t":"세균이 너무 작아 현미경으로도 보기 쉽지 않기 때문에","correct":true},{"t":"세균은 맨눈으로도 잘 보이기 때문에","mis":"SC4-1-u4-X23"},{"t":"세균은 생물이 아니기 때문에","mis":"SC4-1-u4-X21"},{"t":"세균은 그림 속에만 있기 때문에","mis":"SC4-1-u4-X21"}],"explanation":["크기를 떠올려요.","아주 작아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#3','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C27',3,'error','auto','세균이 사는 곳에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X22']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C27","difficulty":3,"kind":"error","stem":"세균이 사는 곳에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「깨끗하게 닦은 책상에는 세균이 살 수 없어.」","correct":true,"mis_target":"SC4-1-u4-X22"},{"t":"친구 가 — 「사람의 피부에도 세균이 살아.」","mis":"SC4-1-u4-X22"},{"t":"친구 다 — 「흙 속과 물속에도 세균이 살아.」","mis":"SC4-1-u4-X22"}],"explanation":["사는 곳 네 군데를 떠올려요.","깨끗해 보여도요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#4','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C26',3,'mc','auto','세균, 짚신벌레, 표고버섯을 크기가 작은 것부터 차례대로 쓴 것은 무엇인가요?',ARRAY['SC4-1-u4-X23']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C26","difficulty":3,"kind":"mc","stem":"세균, 짚신벌레, 표고버섯을 크기가 작은 것부터 차례대로 쓴 것은 무엇인가요?","options":[{"t":"세균 → 짚신벌레 → 표고버섯","correct":true},{"t":"표고버섯 → 짚신벌레 → 세균","mis":"SC4-1-u4-X23"},{"t":"짚신벌레 → 세균 → 표고버섯","mis":"SC4-1-u4-X23"},{"t":"셋 모두 크기가 같다","mis":"SC4-1-u4-X23"}],"explanation":["세균이 가장 작아요.","버섯은 맨눈으로 보여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#5','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C24',3,'mc','auto','다음 가운데 세균인 것은 무엇인가요?',ARRAY['SC4-1-u4-X26']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C24","difficulty":3,"kind":"mc","stem":"다음 가운데 세균인 것은 무엇인가요?","options":[{"t":"대장균","correct":true},{"t":"빵에 핀 곰팡이","mis":"SC4-1-u4-X26"},{"t":"해캄","mis":"SC4-1-u4-X26"},{"t":"짚신벌레","mis":"SC4-1-u4-X26"}],"explanation":["이름을 떠올려요.","오늘 배운 생물이에요.","대장균이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#6','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C29',3,'ox','auto','세균은 따뜻한 곳보다 꽁꽁 언 곳에서 더 잘 늘어나요.',ARRAY['SC4-1-u4-X25']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C29","difficulty":3,"kind":"ox","stem":"세균은 따뜻한 곳보다 꽁꽁 언 곳에서 더 잘 늘어나요.","answer":"X","reason_options":[{"t":"세균은 따뜻하고 살기 좋은 조건에서 더 잘 늘어나기 때문에","correct":true},{"t":"세균은 차가울수록 빨리 늘어나기 때문에","mis":"SC4-1-u4-X25"}],"mis":"SC4-1-u4-X25","explanation":["우유를 떠올려요.","밖에서 빨리 상했어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#7','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C28',3,'mc','auto','세균이 생물이라는 증거로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X23','SC4-1-u4-X26','SC4-1-u4-X21']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C28","difficulty":3,"kind":"mc","stem":"세균이 생물이라는 증거로 알맞은 것은 무엇인가요?","options":[{"t":"양분이 필요하고 수가 늘어난다","correct":true},{"t":"맨눈으로 잘 보인다","mis":"SC4-1-u4-X23"},{"t":"뿌리·줄기·잎이 있다","mis":"SC4-1-u4-X26"},{"t":"움직이지 않으면 생물이 아니다","mis":"SC4-1-u4-X21"}],"explanation":["생물의 특징이에요.","살아가려면 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#8','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C28',4,'mc','auto','친구가 「세균은 먹이를 먹거나 걷는 모습을 본 적이 없으니 생물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X21','SC4-1-u4-X26','SC4-1-u4-X23']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C28","difficulty":4,"kind":"mc","stem":"친구가 「세균은 먹이를 먹거나 걷는 모습을 본 적이 없으니 생물이 아니야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「세균도 살아가는 데 양분이 필요하고 수가 늘어나니까 생물이야.」","correct":true},{"t":"「맞아, 본 적이 없으니 생물이 아니야.」","mis":"SC4-1-u4-X21"},{"t":"「세균은 균류라서 생물이야.」","mis":"SC4-1-u4-X26"},{"t":"「세균은 맨눈으로 보이니까 생물이야.」","mis":"SC4-1-u4-X23"}],"explanation":["눈에 안 보여도 돼요.","생물의 특징을 봐요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#9','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C27',4,'mc','auto','친구가 「세균은 더러운 곳에만 사니까 손이 깨끗해 보이면 씻지 않아도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X22','SC4-1-u4-X21']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C27","difficulty":4,"kind":"mc","stem":"친구가 「세균은 더러운 곳에만 사니까 손이 깨끗해 보이면 씻지 않아도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「세균은 깨끗해 보이는 곳에도 사니까 손을 씻는 것이 좋아.」","correct":true},{"t":"「맞아, 깨끗해 보이면 세균이 없어.」","mis":"SC4-1-u4-X22"},{"t":"「세균은 사람 몸에는 살지 않아.」","mis":"SC4-1-u4-X22"},{"t":"「세균은 생물이 아니라 괜찮아.」","mis":"SC4-1-u4-X21"}],"explanation":["어디에 사는지 떠올려요.","깨끗해 보여도요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L04_challenge#10','sci',4,1,'u4','L04','g4_1_sci_u4_L04_challenge','lesson_challenge','SC4-1-u4-C29',4,'essay','teacher','같은 날 산 우유를 하나는 냉장고 안에, 하나는 따뜻한 방에 두었어요. 어느 우유가 먼저 상할지 쓰고, 그 까닭을 세균의 특징과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C29","difficulty":4,"kind":"essay","stem":"같은 날 산 우유를 하나는 냉장고 안에, 하나는 따뜻한 방에 두었어요. 어느 우유가 먼저 상할지 쓰고, 그 까닭을 세균의 특징과 이어 쓰세요.","answer_guide":{"answer":"예: 따뜻한 방에 둔 우유가 먼저 상한다. 세균은 우리 주변 어디에나 살고, 따뜻해 살기 좋은 조건이 되면 짧은 시간에 많은 수로 늘어나기 때문이다.","scoring_points":["따뜻한 방의 우유를 골랐는가","세균이 어디에나 산다는 것을 썼는가","살기 좋은 조건에서 빨리 늘어난다는 것을 이었는가"]},"explanation":["온도를 견줘요.","세균이 늘어나는 조건이에요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#1','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C34',1,'mc','auto','바다에 사는 일부 원생생물의 수가 갑자기 늘어나 바닷물이 붉게 변하는 현상을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X30']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C34","difficulty":1,"kind":"mc","stem":"바다에 사는 일부 원생생물의 수가 갑자기 늘어나 바닷물이 붉게 변하는 현상을 무엇이라고 하나요?","options":[{"t":"적조 현상","correct":true},{"t":"발효","mis":"SC4-1-u4-X30"},{"t":"분해","mis":"SC4-1-u4-X30"},{"t":"번식","mis":"SC4-1-u4-X30"}],"explanation":["바닷물이 붉어요.","「붉을 적」이에요.","적조 현상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#2','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C31',1,'mc','auto','된장을 만드는 데 이용되는 생물은 무엇인가요?',ARRAY['SC4-1-u4-X29']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C31","difficulty":1,"kind":"mc","stem":"된장을 만드는 데 이용되는 생물은 무엇인가요?","options":[{"t":"곰팡이","correct":true},{"t":"해캄","mis":"SC4-1-u4-X29"},{"t":"짚신벌레","mis":"SC4-1-u4-X29"},{"t":"미역","mis":"SC4-1-u4-X29"}],"explanation":["메주를 떠올려요.","메주에 핀 것이에요.","곰팡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#3','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C30',1,'ox','auto','균류와 세균은 죽은 생물과 낙엽을 분해해요.',ARRAY['SC4-1-u4-X27']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C30","difficulty":1,"kind":"ox","stem":"균류와 세균은 죽은 생물과 낙엽을 분해해요.","answer":"O","reason_options":[{"t":"분해 덕분에 죽은 생물과 낙엽이 쌓이지 않고 주변이 깨끗해지기 때문에","correct":true},{"t":"죽은 생물과 낙엽은 아무도 분해하지 않기 때문에","mis":"SC4-1-u4-X27"}],"mis":"SC4-1-u4-X27","explanation":["조사표를 읽어요.","균류가 하는 일이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["균류 — 죽은 생물과 낙엽을 분해한다 · 된장을 만든다 · 음식을 상하게 한다","원생생물 — 물속에 산소를 공급한다 · 일부는 적조 현상을 일으킨다","세균 — 김치·요구르트를 만든다 · 충치·장염을 일으키기도 한다"],"title":"무리별 영향 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#4','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C31',1,'sa','auto','곰팡이나 세균을 이용해 김치, 된장 같은 음식을 만드는 과정을 무엇이라고 하나요?','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C31","difficulty":1,"kind":"sa","stem":"곰팡이나 세균을 이용해 김치, 된장 같은 음식을 만드는 과정을 무엇이라고 하나요?","answer":["발효"],"explanation":["새로 만난 낱말이에요.","음식을 만들어요.","발효예요."],"mis":"SC4-1-u4-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#5','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C33',2,'match','auto','무리와 미치는 영향을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C33","difficulty":2,"kind":"match","stem":"무리와 미치는 영향을 알맞게 이으세요.","pairs":[{"l":"균류","r":"된장을 만드는 데 이용된다"},{"l":"원생생물","r":"물속에 산소를 공급한다"},{"l":"세균","r":"요구르트를 만드는 데 이용된다"}],"mis":"SC4-1-u4-X29","explanation":["조사표를 읽어요.","무리마다 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["균류 — 죽은 생물과 낙엽을 분해한다 · 된장을 만든다 · 음식을 상하게 한다","원생생물 — 물속에 산소를 공급한다 · 일부는 적조 현상을 일으킨다","세균 — 김치·요구르트를 만든다 · 충치·장염을 일으키기도 한다"],"title":"무리별 영향 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#6','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C33',2,'mc','auto','원생생물이 미치는 영향으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X29']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C33","difficulty":2,"kind":"mc","stem":"원생생물이 미치는 영향으로 알맞은 것은 무엇인가요?","options":[{"t":"물속에 산소를 만들어 공급한다","correct":true},{"t":"치즈를 만드는 데 이용된다","mis":"SC4-1-u4-X29"},{"t":"충치를 일으킨다","mis":"SC4-1-u4-X29"},{"t":"김치를 만드는 데 이용된다","mis":"SC4-1-u4-X29"}],"explanation":["연못을 떠올려요.","물속 생물에게 필요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#7','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C32',2,'ox','auto','세균은 충치나 장염 같은 질병을 일으키기도 해요.',ARRAY['SC4-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C32","difficulty":2,"kind":"ox","stem":"세균은 충치나 장염 같은 질병을 일으키기도 해요.","answer":"O","reason_options":[{"t":"세균 가운데 어떤 종류는 질병을 일으키기도 하기 때문에","correct":true},{"t":"세균은 모두 같은 일만 하므로 질병과 관계없기 때문에","mis":"SC4-1-u4-X32"}],"mis":"SC4-1-u4-X32","explanation":["조사표를 읽어요.","세균 줄이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["균류 — 죽은 생물과 낙엽을 분해한다 · 된장을 만든다 · 음식을 상하게 한다","원생생물 — 물속에 산소를 공급한다 · 일부는 적조 현상을 일으킨다","세균 — 김치·요구르트를 만든다 · 충치·장염을 일으키기도 한다"],"title":"무리별 영향 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#8','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C35',2,'mc','auto','곰팡이가 핀 잼은 먹으면 안 되지만, 곰팡이를 이용한 메주로는 된장을 만들어요. 이것으로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u4-X32','SC4-1-u4-X28']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C35","difficulty":2,"kind":"mc","stem":"곰팡이가 핀 잼은 먹으면 안 되지만, 곰팡이를 이용한 메주로는 된장을 만들어요. 이것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"같은 무리라도 종류에 따라 미치는 영향이 다르다","correct":true},{"t":"곰팡이는 모두 먹어도 된다","mis":"SC4-1-u4-X32"},{"t":"곰팡이는 모두 먹으면 안 된다","mis":"SC4-1-u4-X32"},{"t":"곰팡이는 우리 생활과 관계없다","mis":"SC4-1-u4-X28"}],"explanation":["같은 곰팡이예요.","그런데 다르게 쓰여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#9','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C36',2,'mc','auto','균류, 원생생물, 세균이 모두 사라진다면 일어날 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X33','SC4-1-u4-X28','SC4-1-u4-X29']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C36","difficulty":2,"kind":"mc","stem":"균류, 원생생물, 세균이 모두 사라진다면 일어날 일로 알맞은 것은 무엇인가요?","options":[{"t":"죽은 생물과 낙엽이 분해되지 않고 그대로 쌓인다","correct":true},{"t":"주변이 훨씬 더 깨끗해진다","mis":"SC4-1-u4-X33"},{"t":"아무 일도 일어나지 않는다","mis":"SC4-1-u4-X28"},{"t":"물속 산소가 더 늘어난다","mis":"SC4-1-u4-X29"}],"explanation":["분해는 누가 했나요?","그 생물이 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_basic#10','sci',4,1,'u4','L05','g4_1_sci_u4_L05_basic','lesson_basic','SC4-1-u4-C32',3,'mc','auto','세균이 우리 생활에 미치는 영향을 모두 고른 것은 무엇인가요? ㉠ 김치를 만드는 데 이용됨 ㉡ 음식을 상하게 함 ㉢ 적조 현상을 일으킴 ㉣ 충치를 일으키기도 함',ARRAY['SC4-1-u4-X29','SC4-1-u4-X28']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C32","difficulty":3,"kind":"mc","stem":"세균이 우리 생활에 미치는 영향을 모두 고른 것은 무엇인가요? ㉠ 김치를 만드는 데 이용됨 ㉡ 음식을 상하게 함 ㉢ 적조 현상을 일으킴 ㉣ 충치를 일으키기도 함","options":[{"t":"㉠, ㉡, ㉣","correct":true},{"t":"㉠, ㉢","mis":"SC4-1-u4-X29"},{"t":"㉡, ㉢, ㉣","mis":"SC4-1-u4-X29"},{"t":"㉠만","mis":"SC4-1-u4-X28"}],"explanation":["하나씩 따져요.","㉢은 원생생물이에요.","㉠, ㉡, ㉣이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#1','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C36',2,'blank','auto','「다양한 생물은 사람뿐 아니라 다른 생물과 (      )에도 영향을 미치며 조화롭게 살아가요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X28']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C36","difficulty":2,"kind":"blank","stem":"「다양한 생물은 사람뿐 아니라 다른 생물과 (      )에도 영향을 미치며 조화롭게 살아가요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"환경","correct":true},{"t":"우주","mis":"SC4-1-u4-X28"},{"t":"기계","mis":"SC4-1-u4-X28"},{"t":"달","mis":"SC4-1-u4-X28"}],"explanation":["주변을 떠올려요.","숲과 바다도요.","「환경」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#2','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C33',2,'mc','auto','물속에 사는 원생생물 가운데 일부가 다른 생물에게 주는 도움은 무엇인가요?',ARRAY['SC4-1-u4-X30','SC4-1-u4-X29']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C33","difficulty":2,"kind":"mc","stem":"물속에 사는 원생생물 가운데 일부가 다른 생물에게 주는 도움은 무엇인가요?","options":[{"t":"다른 생물의 먹이가 된다","correct":true},{"t":"바닷물을 붉게 만들어 준다","mis":"SC4-1-u4-X30"},{"t":"물고기의 뼈를 단단하게 한다","mis":"SC4-1-u4-X29"},{"t":"된장을 만들어 준다","mis":"SC4-1-u4-X29"}],"explanation":["작은 생물을 누가 먹을까요?","물속 동물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#3','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C30',3,'error','auto','죽은 생물이 썩는 일에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X27']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C30","difficulty":3,"kind":"error","stem":"죽은 생물이 썩는 일에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「썩는 건 냄새가 나니까 나쁜 일일 뿐이야.」","correct":true,"mis_target":"SC4-1-u4-X27"},{"t":"친구 가 — 「균류와 세균이 죽은 생물을 분해해.」","mis":"SC4-1-u4-X27"},{"t":"친구 나 — 「분해 덕분에 주변이 깨끗해져.」","mis":"SC4-1-u4-X27"}],"explanation":["썩지 않으면 어떨까요?","그대로 쌓여요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#4','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C34',3,'mc','auto','적조 현상에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X30']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C34","difficulty":3,"kind":"mc","stem":"적조 현상에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"바다에 사는 일부 원생생물의 수가 갑자기 늘어나서 생긴다","correct":true},{"t":"세균이 바닷물을 붉게 칠해서 생긴다","mis":"SC4-1-u4-X29"},{"t":"곰팡이가 바다에 퍼져서 생긴다","mis":"SC4-1-u4-X29"},{"t":"바닷물이 꽁꽁 얼어서 생긴다","mis":"SC4-1-u4-X30"}],"explanation":["적조 현상의 뜻이에요.","원생생물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#5','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C31',3,'mc','auto','발효 음식과 이용한 생물을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC4-1-u4-X31']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C31","difficulty":3,"kind":"mc","stem":"발효 음식과 이용한 생물을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"요구르트 — 세균","correct":true},{"t":"된장 — 해캄","mis":"SC4-1-u4-X31"},{"t":"김치 — 짚신벌레","mis":"SC4-1-u4-X31"},{"t":"간장 — 미역","mis":"SC4-1-u4-X31"}],"explanation":["발효에 쓰는 무리예요.","곰팡이나 세균이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#6','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C35',3,'ox','auto','같은 균류라면 우리 생활에 미치는 영향도 모두 똑같아요.',ARRAY['SC4-1-u4-X32']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C35","difficulty":3,"kind":"ox","stem":"같은 균류라면 우리 생활에 미치는 영향도 모두 똑같아요.","answer":"X","reason_options":[{"t":"같은 무리라도 종류에 따라 미치는 영향이 서로 다르기 때문에","correct":true},{"t":"같은 무리에 속하면 하는 일이 모두 같기 때문에","mis":"SC4-1-u4-X32"}],"mis":"SC4-1-u4-X32","explanation":["잼과 메주를 떠올려요.","같은 곰팡이예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#7','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C32',3,'mc','auto','균류가 우리 생활에 미치는 영향만 바르게 고른 것은 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X28']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C32","difficulty":3,"kind":"mc","stem":"균류가 우리 생활에 미치는 영향만 바르게 고른 것은 무엇인가요?","options":[{"t":"된장을 만들고, 음식을 상하게 하고, 습진 같은 피부 질환을 일으키기도 한다","correct":true},{"t":"적조 현상을 일으키고, 물속에 산소를 공급한다","mis":"SC4-1-u4-X29"},{"t":"요구르트를 만들고, 적조 현상을 일으킨다","mis":"SC4-1-u4-X29"},{"t":"균류는 우리 생활에 아무 영향이 없다","mis":"SC4-1-u4-X28"}],"explanation":["균류 줄을 떠올려요.","도움도 어려움도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#8','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C36',4,'mc','auto','친구가 「곰팡이와 세균은 음식을 상하게 하니까 모두 없어져야 해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X33','SC4-1-u4-X28','SC4-1-u4-X32']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C36","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이와 세균은 음식을 상하게 하니까 모두 없어져야 해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「음식을 상하게 하기도 하지만 죽은 생물을 분해하고 음식을 만드는 데도 쓰여. 함께 살아가는 생물이야.」","correct":true},{"t":"「맞아, 모두 없어지면 더 좋아.」","mis":"SC4-1-u4-X33"},{"t":"「곰팡이와 세균은 우리와 아무 관계가 없어.」","mis":"SC4-1-u4-X28"},{"t":"「곰팡이와 세균은 도움만 줘.」","mis":"SC4-1-u4-X32"}],"explanation":["여러 영향을 떠올려요.","없어지면 어떨까요?","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#9','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C30',4,'mc','auto','친구가 「죽은 생물이 썩는 건 나쁜 일이야. 곰팡이도 피고 냄새도 나잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X27','SC4-1-u4-X28']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C30","difficulty":4,"kind":"mc","stem":"친구가 「죽은 생물이 썩는 건 나쁜 일이야. 곰팡이도 피고 냄새도 나잖아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「썩지 않으면 죽은 생물과 낙엽이 그대로 쌓여. 분해 덕분에 주변이 깨끗해져.」","correct":true},{"t":"「맞아, 썩는 일은 모두 나쁜 일이야.」","mis":"SC4-1-u4-X27"},{"t":"「썩는 일은 바닷속에서만 일어나.」","mis":"SC4-1-u4-X27"},{"t":"「썩는 일은 사람과 아무 관계가 없어.」","mis":"SC4-1-u4-X28"}],"explanation":["썩지 않는다면?","그대로 쌓여요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L05_challenge#10','sci',4,1,'u4','L05','g4_1_sci_u4_L05_challenge','lesson_challenge','SC4-1-u4-C35',4,'essay','teacher','균류, 원생생물, 세균 가운데 한 무리를 골라 우리 생활에 도움을 주는 영향과 어려움을 주는 영향을 하나씩 쓰고, 이 생물을 「좋다·나쁘다」 하나로 말하기 어려운 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C35","difficulty":4,"kind":"essay","stem":"균류, 원생생물, 세균 가운데 한 무리를 골라 우리 생활에 도움을 주는 영향과 어려움을 주는 영향을 하나씩 쓰고, 이 생물을 「좋다·나쁘다」 하나로 말하기 어려운 까닭을 쓰세요.","answer_guide":{"answer":"예: 세균은 김치와 요구르트를 만드는 데 이용되지만 충치를 일으키거나 음식을 상하게 하기도 한다. 같은 무리라도 종류에 따라 미치는 영향이 다르고 도움과 어려움을 함께 주기 때문에 좋다·나쁘다 하나로 말하기 어렵다.","scoring_points":["도움을 주는 영향을 하나 썼는가","어려움을 주는 영향을 하나 썼는가","하나로 말하기 어려운 까닭을 썼는가"]},"explanation":["한 무리를 골라요.","양쪽을 다 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["균류 — 죽은 생물과 낙엽을 분해한다 · 된장을 만든다 · 음식을 상하게 한다","원생생물 — 물속에 산소를 공급한다 · 일부는 적조 현상을 일으킨다","세균 — 김치·요구르트를 만든다 · 충치·장염을 일으키기도 한다"],"title":"무리별 영향 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#1','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C37',1,'mc','auto','다양한 생명 현상을 연구하는 학문을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X34']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C37","difficulty":1,"kind":"mc","stem":"다양한 생명 현상을 연구하는 학문을 무엇이라고 하나요?","options":[{"t":"생명과학","correct":true},{"t":"지구과학","mis":"SC4-1-u4-X34"},{"t":"천문학","mis":"SC4-1-u4-X34"},{"t":"수학","mis":"SC4-1-u4-X34"}],"explanation":["오늘 배운 낱말이에요.","생명을 연구해요.","생명과학이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#2','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C41',1,'mc','auto','세균이나 곰팡이가 만드는 물질로 만들어 질병을 치료하는 데 쓰는 것은 무엇인가요?',ARRAY['SC4-1-u4-X37']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C41","difficulty":1,"kind":"mc","stem":"세균이나 곰팡이가 만드는 물질로 만들어 질병을 치료하는 데 쓰는 것은 무엇인가요?","options":[{"t":"항생제","correct":true},{"t":"생물 연료","mis":"SC4-1-u4-X37"},{"t":"친환경 가죽","mis":"SC4-1-u4-X37"},{"t":"인공눈","mis":"SC4-1-u4-X37"}],"explanation":["④를 떠올려요.","병을 치료해요.","항생제예요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#3','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C38',1,'ox','auto','버섯의 균사를 이용해 친환경 가죽을 만들 수 있어요.',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C38","difficulty":1,"kind":"ox","stem":"버섯의 균사를 이용해 친환경 가죽을 만들 수 있어요.","answer":"O","reason_options":[{"t":"버섯의 균사가 촘촘하게 얽혀 튼튼한 성질이 있기 때문에","correct":true},{"t":"버섯은 동물이라 가죽이 있기 때문에","mis":"SC4-1-u4-X36"}],"mis":"SC4-1-u4-X36","explanation":["①을 읽어요.","균사가 얽혀 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#4','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C39',1,'sa','auto','석유를 대신할 수 있도록 원생생물로 만드는 연료를 무엇이라고 하나요? 「○○ 연료」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C39","difficulty":1,"kind":"sa","stem":"석유를 대신할 수 있도록 원생생물로 만드는 연료를 무엇이라고 하나요? 「○○ 연료」의 ○○에 알맞은 말을 쓰세요.","answer":["생물"],"explanation":["②를 읽어요.","생물로 만들어요.","생물이에요."],"mis":"SC4-1-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#5','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C40',2,'match','auto','생명과학 사례와 이용한 생물을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C40","difficulty":2,"kind":"match","stem":"생명과학 사례와 이용한 생물을 알맞게 이으세요.","pairs":[{"l":"친환경 가죽","r":"버섯의 균사"},{"l":"생물 연료","r":"원생생물"},{"l":"바다의 기름 분해","r":"세균"}],"mis":"SC4-1-u4-X36","explanation":["특성과 쓰임을 떠올려요.","무리가 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#6','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C37',2,'mc','auto','생명과학이 우리 생활에 주는 도움으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X34','SC4-1-u4-X39']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C37","difficulty":2,"kind":"mc","stem":"생명과학이 우리 생활에 주는 도움으로 알맞은 것은 무엇인가요?","options":[{"t":"생물의 여러 기능을 연구해 생활 속 문제를 해결한다","correct":true},{"t":"땅과 바위만 연구한다","mis":"SC4-1-u4-X34"},{"t":"별과 우주만 연구한다","mis":"SC4-1-u4-X34"},{"t":"실험실 안에서만 쓰여 생활과는 관계없다","mis":"SC4-1-u4-X39"}],"explanation":["생명과학의 뜻을 떠올려요.","문제를 풀어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#7','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C42',2,'ox','auto','모든 곰팡이와 세균에서 질병을 치료하는 물질을 얻을 수 있어요.',ARRAY['SC4-1-u4-X35']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C42","difficulty":2,"kind":"ox","stem":"모든 곰팡이와 세균에서 질병을 치료하는 물질을 얻을 수 있어요.","answer":"X","reason_options":[{"t":"아주 많은 종류 가운데 일부에서만 얻을 수 있고 긴 연구가 필요하기 때문에","correct":true},{"t":"곰팡이와 세균은 모두 약이 되기 때문에","mis":"SC4-1-u4-X35"}],"mis":"SC4-1-u4-X35","explanation":["아주 특별한 경우예요.","일부에서만요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#8','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C40',2,'mc','auto','세균을 이용한 생명과학 사례는 무엇인가요?',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C40","difficulty":2,"kind":"mc","stem":"세균을 이용한 생명과학 사례는 무엇인가요?","options":[{"t":"스키장에서 인공눈을 만든다","correct":true},{"t":"버섯 균사로 친환경 가죽을 만든다","mis":"SC4-1-u4-X36"},{"t":"클로렐라로 건강식품을 만든다","mis":"SC4-1-u4-X36"},{"t":"해캄으로 생물 연료를 만든다","mis":"SC4-1-u4-X36"}],"explanation":["무리를 따져요.","버섯·해캄은 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#9','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C39',2,'mc','auto','클로렐라로 만드는 것은 무엇인가요?',ARRAY['SC4-1-u4-X37','SC4-1-u4-X36']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C39","difficulty":2,"kind":"mc","stem":"클로렐라로 만드는 것은 무엇인가요?","options":[{"t":"건강식품","correct":true},{"t":"항생제","mis":"SC4-1-u4-X37"},{"t":"친환경 가죽","mis":"SC4-1-u4-X36"},{"t":"인공눈","mis":"SC4-1-u4-X36"}],"explanation":["원생생물이에요.","먹는 것이에요.","건강식품이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_basic#10','sci',4,1,'u4','L06','g4_1_sci_u4_L06_basic','lesson_basic','SC4-1-u4-C43',3,'mc','auto','하수 처리장에서 오염된 물을 깨끗이 하는 데 균류를 이용하는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X38']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C43","difficulty":3,"kind":"mc","stem":"하수 처리장에서 오염된 물을 깨끗이 하는 데 균류를 이용하는 까닭은 무엇인가요?","options":[{"t":"균류가 죽은 생물을 분해해 다른 생물이 이용할 수 있게 하기 때문에","correct":true},{"t":"균류가 물을 예쁜 색으로 바꾸기 때문에","mis":"SC4-1-u4-X38"},{"t":"균류가 물을 차갑게 만들기 때문에","mis":"SC4-1-u4-X38"},{"t":"균류가 물을 빠르게 흐르게 하기 때문에","mis":"SC4-1-u4-X38"}],"explanation":["균류가 하는 일을 떠올려요.","분해예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
