INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#3','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C40',3,'error','auto','생명과학 사례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C40","difficulty":3,"kind":"error","stem":"생명과학 사례를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바다에 퍼진 기름은 버섯 균사로 분해해.」","correct":true,"mis_target":"SC4-1-u4-X36"},{"t":"친구 가 — 「기름을 분해하는 세균으로 바다 오염을 줄여.」","mis":"SC4-1-u4-X36"},{"t":"친구 다 — 「분해가 잘되는 친환경 플라스틱도 세균으로 만들어.」","mis":"SC4-1-u4-X36"}],"explanation":["③을 읽어요.","기름은 세균이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#4','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C39',3,'mc','auto','원생생물로 생물 연료를 만들 수 있는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X36','SC4-1-u4-X38']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C39","difficulty":3,"kind":"mc","stem":"원생생물로 생물 연료를 만들 수 있는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"스스로 양분을 만드는 특성이 있기 때문에","correct":true},{"t":"균사가 촘촘하게 얽혀 있기 때문에","mis":"SC4-1-u4-X36"},{"t":"기름을 먹이로 삼기 때문에","mis":"SC4-1-u4-X36"},{"t":"바닷물을 붉게 만들기 때문에","mis":"SC4-1-u4-X38"}],"explanation":["②를 읽어요.","양분을 만들어요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#5','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C37',3,'mc','auto','생명과학이 쓰이는 곳을 모두 고른 것은 무엇인가요? ㉠ 식량 ㉡ 연료 ㉢ 환경 ㉣ 질병 치료',ARRAY['SC4-1-u4-X39']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C37","difficulty":3,"kind":"mc","stem":"생명과학이 쓰이는 곳을 모두 고른 것은 무엇인가요? ㉠ 식량 ㉡ 연료 ㉢ 환경 ㉣ 질병 치료","options":[{"t":"㉠, ㉡, ㉢, ㉣","correct":true},{"t":"㉠만","mis":"SC4-1-u4-X39"},{"t":"㉡, ㉢","mis":"SC4-1-u4-X39"},{"t":"㉣만","mis":"SC4-1-u4-X39"}],"explanation":["여러 문제를 풀어요.","모두 해당해요.","네 가지 모두예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#6','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C38',3,'ox','auto','버섯 균사로 만든 친환경 가죽은 자연에서 분해되는 성질이 있어요.',ARRAY['SC4-1-u4-X38']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C38","difficulty":3,"kind":"ox","stem":"버섯 균사로 만든 친환경 가죽은 자연에서 분해되는 성질이 있어요.","answer":"O","reason_options":[{"t":"버섯 균사로 만든 가죽은 쓰고 난 뒤 자연에서 분해되기 때문에","correct":true},{"t":"버섯 균사로 만든 가죽은 절대 분해되지 않기 때문에","mis":"SC4-1-u4-X38"}],"mis":"SC4-1-u4-X38","explanation":["친환경이라는 말을 떠올려요.","자연으로 돌아가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#7','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C41',3,'mc','auto','항생제를 만드는 데 이용하는 것을 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u4-X37']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C41","difficulty":3,"kind":"mc","stem":"항생제를 만드는 데 이용하는 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"세균이나 곰팡이가 만드는 물질","correct":true},{"t":"해캄이 만드는 산소","mis":"SC4-1-u4-X37"},{"t":"버섯의 갓","mis":"SC4-1-u4-X37"},{"t":"바닷물의 소금","mis":"SC4-1-u4-X37"}],"explanation":["④를 읽어요.","만드는 물질이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#8','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C42',4,'mc','auto','친구가 「푸른곰팡이로 약을 만들었으니 집에 핀 곰팡이로도 약을 만들 수 있겠다.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X35','SC4-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C42","difficulty":4,"kind":"mc","stem":"친구가 「푸른곰팡이로 약을 만들었으니 집에 핀 곰팡이로도 약을 만들 수 있겠다.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「약이 되는 물질은 일부 곰팡이에서만 얻을 수 있고 오랜 연구가 필요해.」","correct":true},{"t":"「맞아, 곰팡이는 모두 약이 돼.」","mis":"SC4-1-u4-X35"},{"t":"「곰팡이로는 어떤 약도 만들 수 없어.」","mis":"SC4-1-u4-X35"},{"t":"「약은 해캄으로만 만들어.」","mis":"SC4-1-u4-X37"}],"explanation":["특별한 경우예요.","연구도 오래 걸려요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#9','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C40',4,'mc','auto','친구가 「세균은 병만 일으키니까 생활에 쓸 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X39','SC4-1-u4-X36','SC4-1-u4-X21']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C40","difficulty":4,"kind":"mc","stem":"친구가 「세균은 병만 일으키니까 생활에 쓸 수 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「세균은 기름을 분해하거나 인공눈을 만드는 데도 이용돼.」","correct":true},{"t":"「맞아, 세균은 쓸 데가 없어.」","mis":"SC4-1-u4-X39"},{"t":"「세균은 친환경 가죽을 만드는 데만 써.」","mis":"SC4-1-u4-X36"},{"t":"「세균은 생물이 아니라서 쓸 수 없어.」","mis":"SC4-1-u4-X21"}],"explanation":["세균을 이용한 예를 떠올려요.","여러 가지예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L06_challenge#10','sci',4,1,'u4','L06','g4_1_sci_u4_L06_challenge','lesson_challenge','SC4-1-u4-C37',4,'essay','teacher','바다에 기름이 퍼져 오염되었어요. 생명과학을 이용해 이 문제를 어떻게 해결할 수 있을지 쓰고, 생명과학이 무엇인지 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C37","difficulty":4,"kind":"essay","stem":"바다에 기름이 퍼져 오염되었어요. 생명과학을 이용해 이 문제를 어떻게 해결할 수 있을지 쓰고, 생명과학이 무엇인지 함께 쓰세요.","answer_guide":{"answer":"예: 기름을 먹이로 삼아 분해하는 세균을 이용해 바다에 퍼진 기름을 없앨 수 있다. 생명과학은 다양한 생명 현상을 연구하는 학문으로, 생물의 기능을 연구해 생활 속 문제를 해결하는 데 도움을 준다.","scoring_points":["세균으로 기름을 분해한다고 썼는가","생명과학의 뜻을 썼는가","생활 속 문제 해결과 이었는가"]},"explanation":["③을 떠올려요.","생명과학의 뜻도요.","두 가지를 써요."],"asset":{"type":"passage","lines":["① 버섯의 균사는 촘촘하게 얽혀 있다 → 친환경 가죽","② 원생생물은 양분을 만드는 특성이 있다 → 생물 연료","③ 어떤 세균은 기름을 먹이로 삼는다 → 바다 오염 해결","④ 곰팡이나 세균이 만드는 물질 → 항생제"],"title":"특성과 쓰임 잇기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#1','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C44',1,'mc','auto','생명과학 홍보 활동의 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X40']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C44","difficulty":1,"kind":"mc","stem":"생명과학 홍보 활동의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"계획해요 → 실행해요 → 홍보해요","correct":true},{"t":"홍보해요 → 계획해요 → 실행해요","mis":"SC4-1-u4-X40"},{"t":"실행해요 → 홍보해요 → 계획해요","mis":"SC4-1-u4-X40"},{"t":"홍보해요 한 가지만 한다","mis":"SC4-1-u4-X40"}],"explanation":["먼저 정해요.","만들고 알려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#2','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C47',1,'mc','auto','조사한 사진이나 자료를 쓸 때 꼭 해야 할 일은 무엇인가요?',ARRAY['SC4-1-u4-X41','SC4-1-u4-X43']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C47","difficulty":1,"kind":"mc","stem":"조사한 사진이나 자료를 쓸 때 꼭 해야 할 일은 무엇인가요?","options":[{"t":"가져온 곳, 곧 출처를 밝힌다","correct":true},{"t":"사진의 색을 모두 바꾼다","mis":"SC4-1-u4-X41"},{"t":"아무에게도 알리지 않는다","mis":"SC4-1-u4-X41"},{"t":"사진을 가장 크게 키운다","mis":"SC4-1-u4-X43"}],"explanation":["어디서 가져왔나요?","밝혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#3','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C48',1,'ox','auto','다른 모둠 자료에서는 잘한 점을 찾아 칭찬해요.',ARRAY['SC4-1-u4-X42']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C48","difficulty":1,"kind":"ox","stem":"다른 모둠 자료에서는 잘한 점을 찾아 칭찬해요.","answer":"O","reason_options":[{"t":"칭찬과 함께 보완할 점을 나누면 서로 더 좋게 고칠 수 있기 때문에","correct":true},{"t":"다른 모둠 자료에는 나쁜 점만 말해야 하기 때문에","mis":"SC4-1-u4-X42"}],"mis":"SC4-1-u4-X42","explanation":["서로 보며 고쳐요.","잘한 점도 찾아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#4','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C49',1,'sa','auto','특정한 해충에게만 질병을 일으키는 곰팡이나 세균으로 만든 친환경 농약을 무엇이라고 하나요? 「○○ 농약」의 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C49","difficulty":1,"kind":"sa","stem":"특정한 해충에게만 질병을 일으키는 곰팡이나 세균으로 만든 친환경 농약을 무엇이라고 하나요? 「○○ 농약」의 ○○에 알맞은 말을 쓰세요.","answer":["생물"],"explanation":["계획의 사례를 읽어요.","생물로 만들어요.","생물이에요."],"mis":"SC4-1-u4-X45"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#5','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C45',2,'match','auto','홍보 계획에서 정할 것과 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C45","difficulty":2,"kind":"match","stem":"홍보 계획에서 정할 것과 예를 알맞게 이으세요.","pairs":[{"l":"어떤 사례를","r":"생물 농약"},{"l":"어디에","r":"학교 게시판"},{"l":"어떤 형태로","r":"포스터"}],"mis":"SC4-1-u4-X44","explanation":["계획을 읽어요.","하나씩 짝이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["어떤 사례를? — 해충에게만 질병을 일으키는 세균으로 만든 생물 농약","어디에? — 학교 게시판","어떤 형태로? — 포스터","누가? — 자료 조사, 포스터 만들기, 꾸미고 고치기를 나누어 맡음"],"title":"우리 모둠 홍보 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#6','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C46',2,'mc','auto','소개 자료를 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X40']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C46","difficulty":2,"kind":"mc","stem":"소개 자료를 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"조사하기 → 정리하기 → 만들기","correct":true},{"t":"만들기 → 조사하기 → 정리하기","mis":"SC4-1-u4-X40"},{"t":"정리하기 → 만들기 → 조사하기","mis":"SC4-1-u4-X40"},{"t":"만들기만 한다","mis":"SC4-1-u4-X40"}],"explanation":["먼저 알아봐요.","간추린 뒤 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#7','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C47',2,'ox','auto','재미있는 내용이라면 거짓 정보라도 소개 자료에 넣어도 돼요.',ARRAY['SC4-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C47","difficulty":2,"kind":"ox","stem":"재미있는 내용이라면 거짓 정보라도 소개 자료에 넣어도 돼요.","answer":"X","reason_options":[{"t":"옳은 정보와 거짓 정보를 가려 사실만 알려야 하기 때문에","correct":true},{"t":"재미있으면 사실인지는 중요하지 않기 때문에","mis":"SC4-1-u4-X41"}],"mis":"SC4-1-u4-X41","explanation":["사실을 알려야 해요.","거짓은 안 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#8','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C49',2,'mc','auto','생물 농약을 「친환경」이라고 하는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X45']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C49","difficulty":2,"kind":"mc","stem":"생물 농약을 「친환경」이라고 하는 까닭은 무엇인가요?","options":[{"t":"특정한 해충에게만 작용해 다른 생물에게 피해를 주지 않기 때문에","correct":true},{"t":"모든 생물을 한꺼번에 없애기 때문에","mis":"SC4-1-u4-X45"},{"t":"색깔이 초록색이기 때문에","mis":"SC4-1-u4-X45"},{"t":"공장에서만 만들기 때문에","mis":"SC4-1-u4-X45"}],"explanation":["누구에게 작용하나요?","해충에게만요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#9','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C47',2,'mc','auto','컴퓨터로 자료를 만든 뒤 마지막에 해야 할 일은 무엇인가요?',ARRAY['SC4-1-u4-X41']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C47","difficulty":2,"kind":"mc","stem":"컴퓨터로 자료를 만든 뒤 마지막에 해야 할 일은 무엇인가요?","options":[{"t":"반드시 로그아웃한다","correct":true},{"t":"로그인한 채로 그냥 둔다","mis":"SC4-1-u4-X41"},{"t":"친구 계정으로 바꿔 둔다","mis":"SC4-1-u4-X41"},{"t":"자료의 출처를 지운다","mis":"SC4-1-u4-X41"}],"explanation":["내 계정을 지켜요.","나가기를 눌러요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_basic#10','sci',4,1,'u4','L07','g4_1_sci_u4_L07_basic','lesson_basic','SC4-1-u4-C46',3,'mc','auto','좋은 소개 자료의 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X43']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C46","difficulty":3,"kind":"mc","stem":"좋은 소개 자료의 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"간단하면서 눈길을 끌고 꼭 필요한 내용을 담았다","correct":true},{"t":"아는 것을 빠짐없이 모두 넣었다","mis":"SC4-1-u4-X43"},{"t":"어려운 낱말을 많이 넣었다","mis":"SC4-1-u4-X43"},{"t":"사진 없이 긴 글로만 채웠다","mis":"SC4-1-u4-X43"}],"explanation":["한눈에 보여야 해요.","꼭 필요한 것만요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#1','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C44',2,'blank','auto','「홍보 활동은 계획해요, (      ), 홍보해요의 차례로 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X40']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C44","difficulty":2,"kind":"blank","stem":"「홍보 활동은 계획해요, (      ), 홍보해요의 차례로 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"실행해요","correct":true},{"t":"포기해요","mis":"SC4-1-u4-X40"},{"t":"구경해요","mis":"SC4-1-u4-X40"},{"t":"미뤄요","mis":"SC4-1-u4-X40"}],"explanation":["계획한 뒤에 해요.","자료를 만들어요.","「실행해요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#2','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C50',2,'mc','auto','「편지 속 낱말을 맞혀라」 놀이에서 틀린 문장을 만났을 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X46']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C50","difficulty":2,"kind":"mc","stem":"「편지 속 낱말을 맞혀라」 놀이에서 틀린 문장을 만났을 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"어디가 틀렸는지 찾아 옳은 내용으로 고친다","correct":true},{"t":"틀린 문장은 그냥 넘긴다","mis":"SC4-1-u4-X46"},{"t":"아무 글자나 골라 넣는다","mis":"SC4-1-u4-X46"},{"t":"놀이를 그만둔다","mis":"SC4-1-u4-X46"}],"explanation":["틀린 곳을 찾아요.","옳게 바꿔요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#3','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C50',3,'error','auto','편지 속 문장을 보고 친구들이 판단했어요. 잘못 판단한 친구는 누구인가요?',ARRAY['SC4-1-u4-X46']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C50","difficulty":3,"kind":"error","stem":"편지 속 문장을 보고 친구들이 판단했어요. 잘못 판단한 친구는 누구인가요?","options":[{"t":"친구 가 — 「짚신벌레는 균사로 이루어져 포자로 번식해.」는 옳아요.","correct":true,"mis_target":"SC4-1-u4-X46"},{"t":"친구 나 — 「버섯과 곰팡이 같은 생물을 균류라고 해.」는 옳아요.","mis":"SC4-1-u4-X46"},{"t":"친구 다 — 「해캄으로 요구르트를 만들어.」는 틀려요.","mis":"SC4-1-u4-X46"}],"explanation":["균사와 포자는 어느 무리일까요?","짚신벌레는 원생생물이에요.","친구 가가 잘못 판단했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#4','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C45',3,'mc','auto','홍보 계획에서 역할을 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X44']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C45","difficulty":3,"kind":"mc","stem":"홍보 계획에서 역할을 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"자료 조사, 만들기, 꾸미고 고치기를 모둠원이 나누어 맡는다","correct":true},{"t":"가장 잘하는 한 사람이 모두 맡는다","mis":"SC4-1-u4-X44"},{"t":"역할 없이 각자 따로 만든다","mis":"SC4-1-u4-X44"},{"t":"맡을 일이 없는 친구는 뺀다","mis":"SC4-1-u4-X44"}],"explanation":["함께 만들어요.","골고루 나눠요.","첫 번째예요."],"asset":{"type":"passage","lines":["어떤 사례를? — 해충에게만 질병을 일으키는 세균으로 만든 생물 농약","어디에? — 학교 게시판","어떤 형태로? — 포스터","누가? — 자료 조사, 포스터 만들기, 꾸미고 고치기를 나누어 맡음"],"title":"우리 모둠 홍보 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#5','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C48',3,'mc','auto','옆 모둠 자료의 글씨가 작아 잘 안 보일 때 보완할 점을 알맞게 말한 것은 무엇인가요?',ARRAY['SC4-1-u4-X42']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C48","difficulty":3,"kind":"mc","stem":"옆 모둠 자료의 글씨가 작아 잘 안 보일 때 보완할 점을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「사진이 눈에 잘 들어와요. 글씨를 조금 키우면 더 좋겠어요.」","correct":true},{"t":"「하나도 안 보여요. 다시 만드세요.」","mis":"SC4-1-u4-X42"},{"t":"아무 말도 하지 않고 지나간다","mis":"SC4-1-u4-X42"},{"t":"여러 사람 앞에서 잘못만 크게 말한다","mis":"SC4-1-u4-X42"}],"explanation":["칭찬부터 해요.","마음이 상하지 않게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#6','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C46',3,'ox','auto','소개 자료에는 아는 내용을 빠짐없이 모두 넣을수록 좋아요.',ARRAY['SC4-1-u4-X43']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C46","difficulty":3,"kind":"ox","stem":"소개 자료에는 아는 내용을 빠짐없이 모두 넣을수록 좋아요.","answer":"X","reason_options":[{"t":"간단하면서 꼭 필요한 내용만 골라야 눈길을 끌기 때문에","correct":true},{"t":"내용이 많을수록 언제나 좋은 자료이기 때문에","mis":"SC4-1-u4-X43"}],"mis":"SC4-1-u4-X43","explanation":["한눈에 보여야 해요.","꼭 필요한 것만요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#7','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C49',3,'mc','auto','생물 농약에 이용하는 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X45','SC4-1-u4-X29']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C49","difficulty":3,"kind":"mc","stem":"생물 농약에 이용하는 생물로 알맞은 것은 무엇인가요?","options":[{"t":"특정한 해충에게만 질병을 일으키는 곰팡이나 세균","correct":true},{"t":"모든 곤충을 없애는 생물","mis":"SC4-1-u4-X45"},{"t":"해충을 키워 주는 생물","mis":"SC4-1-u4-X45"},{"t":"바닷물을 붉게 만드는 원생생물","mis":"SC4-1-u4-X29"}],"explanation":["계획의 사례를 읽어요.","해충에게만이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["어떤 사례를? — 해충에게만 질병을 일으키는 세균으로 만든 생물 농약","어디에? — 학교 게시판","어떤 형태로? — 포스터","누가? — 자료 조사, 포스터 만들기, 꾸미고 고치기를 나누어 맡음"],"title":"우리 모둠 홍보 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#8','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C47',4,'mc','auto','친구가 「인터넷에서 찾은 사진이니까 출처는 안 적어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X41']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C47","difficulty":4,"kind":"mc","stem":"친구가 「인터넷에서 찾은 사진이니까 출처는 안 적어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「사진과 자료를 가져온 곳을 꼭 적어야 해. 그래야 믿을 수 있는 자료가 돼.」","correct":true},{"t":"「맞아, 인터넷 사진은 아무렇게나 써도 돼.」","mis":"SC4-1-u4-X41"},{"t":"「출처 대신 내 이름을 적자.」","mis":"SC4-1-u4-X41"},{"t":"「사진을 지우고 지어낸 정보로 채우자.」","mis":"SC4-1-u4-X41"}],"explanation":["어디서 가져왔나요?","밝혀야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#9','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C48',4,'mc','auto','친구가 「다른 모둠 자료에 댓글을 쓸 때는 아쉬운 점만 짧게 쓰자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X42']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C48","difficulty":4,"kind":"mc","stem":"친구가 「다른 모둠 자료에 댓글을 쓸 때는 아쉬운 점만 짧게 쓰자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「잘한 점을 구체적으로 칭찬하고, 보완할 점은 기분이 상하지 않게 함께 써 주자.」","correct":true},{"t":"「맞아, 아쉬운 점만 쓰면 돼.」","mis":"SC4-1-u4-X42"},{"t":"「댓글은 아무렇게나 써도 돼.」","mis":"SC4-1-u4-X42"},{"t":"「댓글 대신 그 자료를 지워 주자.」","mis":"SC4-1-u4-X42"}],"explanation":["예의를 떠올려요.","칭찬도 함께요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L07_challenge#10','sci',4,1,'u4','L07','g4_1_sci_u4_L07_challenge','lesson_challenge','SC4-1-u4-C45',4,'essay','teacher','우리 반이 생명과학 사례 하나를 홍보하려고 해요. 홍보 계획의 네 가지(사례, 홍보할 곳, 형태, 역할)를 정해 쓰고, 소개 자료를 만들 때 지킬 점을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C45","difficulty":4,"kind":"essay","stem":"우리 반이 생명과학 사례 하나를 홍보하려고 해요. 홍보 계획의 네 가지(사례, 홍보할 곳, 형태, 역할)를 정해 쓰고, 소개 자료를 만들 때 지킬 점을 하나 쓰세요.","answer_guide":{"answer":"예: 사례는 해충에게만 질병을 일으키는 세균으로 만든 생물 농약, 홍보할 곳은 학교 게시판, 형태는 포스터, 역할은 자료 조사·포스터 만들기·꾸미고 고치기로 나눈다. 사진과 자료를 쓸 때에는 출처를 밝힌다.","scoring_points":["네 가지를 모두 정했는가","역할을 나누어 맡았는가","지킬 점(출처·사실 확인·간단하게 등)을 썼는가"]},"explanation":["네 가지를 떠올려요.","역할도 나눠요.","지킬 점도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#1','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C51',1,'mc','auto','생명과학 연구원이 하는 일은 무엇인가요?',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C51","difficulty":1,"kind":"mc","stem":"생명과학 연구원이 하는 일은 무엇인가요?","options":[{"t":"생물을 연구해 다양한 생명 현상을 탐구한다","correct":true},{"t":"날씨를 예보한다","mis":"SC4-1-u4-X47"},{"t":"화산과 지진을 예측한다","mis":"SC4-1-u4-X47"},{"t":"우주로 가는 로켓을 만든다","mis":"SC4-1-u4-X47"}],"explanation":["생명과학을 떠올려요.","생물을 연구해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#2','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C52',1,'mc','auto','병과 해충에 강하고 많이 생산되는 작물을 만드는 연구는 어느 갈래인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C52","difficulty":1,"kind":"mc","stem":"병과 해충에 강하고 많이 생산되는 작물을 만드는 연구는 어느 갈래인가요?","options":[{"t":"새로운 품종 개발","correct":true},{"t":"바이오 에너지","mis":"SC4-1-u4-X48"},{"t":"의약품 만들기","mis":"SC4-1-u4-X48"},{"t":"질병 분석","mis":"SC4-1-u4-X48"}],"explanation":["작물을 만들어요.","새 품종이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#3','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C51',1,'ox','auto','생명과학 연구원은 눈에 보이지 않는 생물도 연구해요.',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C51","difficulty":1,"kind":"ox","stem":"생명과학 연구원은 눈에 보이지 않는 생물도 연구해요.","answer":"O","reason_options":[{"t":"사람·동물·식물은 물론 아주 작은 생물까지 연구하기 때문에","correct":true},{"t":"연구원은 눈에 보이는 생물만 연구하기 때문에","mis":"SC4-1-u4-X47"}],"mis":"SC4-1-u4-X47","explanation":["이 단원의 생물을 떠올려요.","세균도 연구해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#4','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C52',1,'sa','auto','가축의 분뇨나 버려지는 물질로 전기를 얻는 방법을 연구하는 갈래는 「○○○ 에너지」예요. ○○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC4-1-u4-C52","difficulty":1,"kind":"sa","stem":"가축의 분뇨나 버려지는 물질로 전기를 얻는 방법을 연구하는 갈래는 「○○○ 에너지」예요. ○○○에 알맞은 말을 쓰세요.","answer":["바이오"],"explanation":["네 갈래를 떠올려요.","첫 번째 갈래예요.","바이오예요."],"mis":"SC4-1-u4-X48"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#5','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C52',2,'match','auto','연구 갈래와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC4-1-u4-C52","difficulty":2,"kind":"match","stem":"연구 갈래와 하는 일을 알맞게 이으세요.","pairs":[{"l":"바이오 에너지","r":"친환경 연료 개발"},{"l":"새로운 품종","r":"미래의 새 식재료 개발"},{"l":"의약품","r":"병을 치료하는 약 개발"}],"mis":"SC4-1-u4-X48","explanation":["갈래 이름을 읽어요.","하는 일이 달라요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#6','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C53',2,'mc','auto','연구원이 건강한 사람의 대변에서 걸러 내는 것은 무엇인가요?',ARRAY['SC4-1-u4-X49']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C53","difficulty":2,"kind":"mc","stem":"연구원이 건강한 사람의 대변에서 걸러 내는 것은 무엇인가요?","options":[{"t":"이로운 세균","correct":true},{"t":"세균을 모두 없애는 물질","mis":"SC4-1-u4-X49"},{"t":"곰팡이 포자","mis":"SC4-1-u4-X49"},{"t":"해캄","mis":"SC4-1-u4-X49"}],"explanation":["②를 읽어요.","세균이에요.","이로운 세균이에요."],"asset":{"type":"passage","lines":["① 건강한 사람에게 대변을 기증받는다.","② 대변에서 이로운 세균을 걸러 낸다.","③ 걸러 낸 세균을 환자의 장 속에 넣어 준다.","④ 이로운 세균이 질병 치료를 돕는다."],"title":"첨단 과학 — 이로운 세균 연구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#7','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C51',2,'ox','auto','요즘 생명과학 연구원은 의료·환경·전자·기계 같은 다른 분야와 힘을 합해 연구해요.',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C51","difficulty":2,"kind":"ox","stem":"요즘 생명과학 연구원은 의료·환경·전자·기계 같은 다른 분야와 힘을 합해 연구해요.","answer":"O","reason_options":[{"t":"다른 분야와 함께하면 더 다양한 연구를 할 수 있기 때문에","correct":true},{"t":"연구원은 언제나 혼자서만 연구하기 때문에","mis":"SC4-1-u4-X47"}],"mis":"SC4-1-u4-X47","explanation":["함께하면 어떨까요?","연구가 넓어져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#8','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C52',2,'mc','auto','생물에서 얻은 물질로 만든 의약품의 좋은 점은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C52","difficulty":2,"kind":"mc","stem":"생물에서 얻은 물질로 만든 의약품의 좋은 점은 무엇인가요?","options":[{"t":"독성이 낮고 부작용이 적은 편이다","correct":true},{"t":"어떤 병이든 단번에 낫게 한다","mis":"SC4-1-u4-X48"},{"t":"만드는 데 연구가 필요 없다","mis":"SC4-1-u4-X48"},{"t":"색깔이 예쁘다","mis":"SC4-1-u4-X48"}],"explanation":["의약품 갈래를 떠올려요.","몸에 덜 해로워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#9','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C54',2,'mc','auto','「나라면 어떤 연구를 하고 싶은가?」를 생각할 때 알맞은 태도는 무엇인가요?',ARRAY['SC4-1-u4-X50']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C54","difficulty":2,"kind":"mc","stem":"「나라면 어떤 연구를 하고 싶은가?」를 생각할 때 알맞은 태도는 무엇인가요?","options":[{"t":"내가 풀고 싶은 문제를 떠올려 본다","correct":true},{"t":"정해진 정답 하나를 찾는다","mis":"SC4-1-u4-X50"},{"t":"친구 답을 그대로 따라 쓴다","mis":"SC4-1-u4-X50"},{"t":"생각하지 않고 넘어간다","mis":"SC4-1-u4-X50"}],"explanation":["정답은 없어요.","내 생각이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_basic#10','sci',4,1,'u4','L08','g4_1_sci_u4_L08_basic','lesson_basic','SC4-1-u4-C53',3,'mc','auto','걸러 낸 이로운 세균을 환자의 장 속에 넣어 주는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X49']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C53","difficulty":3,"kind":"mc","stem":"걸러 낸 이로운 세균을 환자의 장 속에 넣어 주는 까닭은 무엇인가요?","options":[{"t":"이로운 세균이 질병을 치료하는 데 도움을 주기 때문에","correct":true},{"t":"세균을 모두 없애기 위해서","mis":"SC4-1-u4-X49"},{"t":"환자의 몸을 차갑게 하려고","mis":"SC4-1-u4-X49"},{"t":"환자의 몸 색깔을 바꾸려고","mis":"SC4-1-u4-X49"}],"explanation":["④를 읽어요.","치료를 도와요.","첫 번째예요."],"asset":{"type":"passage","lines":["① 건강한 사람에게 대변을 기증받는다.","② 대변에서 이로운 세균을 걸러 낸다.","③ 걸러 낸 세균을 환자의 장 속에 넣어 준다.","④ 이로운 세균이 질병 치료를 돕는다."],"title":"첨단 과학 — 이로운 세균 연구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#1','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C52',2,'blank','auto','「새로운 (      ) 개발은 미래의 식량 부족에 대비하는 연구예요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C52","difficulty":2,"kind":"blank","stem":"「새로운 (      ) 개발은 미래의 식량 부족에 대비하는 연구예요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"품종","correct":true},{"t":"연료","mis":"SC4-1-u4-X48"},{"t":"의약품","mis":"SC4-1-u4-X48"},{"t":"기계","mis":"SC4-1-u4-X48"}],"explanation":["먹을거리를 만들어요.","작물의 종류예요.","「품종」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#2','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C51',2,'mc','auto','생명과학 연구원이 연구하는 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C51","difficulty":2,"kind":"mc","stem":"생명과학 연구원이 연구하는 생물로 알맞은 것은 무엇인가요?","options":[{"t":"사람, 동물, 식물, 눈에 보이지 않는 생물까지","correct":true},{"t":"사람만","mis":"SC4-1-u4-X47"},{"t":"눈에 보이는 큰 동물만","mis":"SC4-1-u4-X47"},{"t":"식물만","mis":"SC4-1-u4-X47"}],"explanation":["넓게 연구해요.","보이지 않는 생물도요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#3','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C53',3,'error','auto','첨단 과학 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC4-1-u4-X49']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C53","difficulty":3,"kind":"error","stem":"첨단 과학 이야기를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세균은 늘 해로우니 몸에 넣으면 안 돼.」","correct":true,"mis_target":"SC4-1-u4-X49"},{"t":"친구 가 — 「이로운 세균을 걸러 내어 치료에 써.」","mis":"SC4-1-u4-X49"},{"t":"친구 나 — 「세균이 질병 치료를 돕기도 해.」","mis":"SC4-1-u4-X49"}],"explanation":["②와 ④를 읽어요.","이로운 세균이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 건강한 사람에게 대변을 기증받는다.","② 대변에서 이로운 세균을 걸러 낸다.","③ 걸러 낸 세균을 환자의 장 속에 넣어 준다.","④ 이로운 세균이 질병 치료를 돕는다."],"title":"첨단 과학 — 이로운 세균 연구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#4','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C54',3,'mc','auto','단원에서 배운 생물과 연구가 바르게 이어진 것은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C54","difficulty":3,"kind":"mc","stem":"단원에서 배운 생물과 연구가 바르게 이어진 것은 무엇인가요?","options":[{"t":"균류 — 곰팡이가 만드는 물질로 병을 치료하는 약 연구","correct":true},{"t":"세균 — 균사로 친환경 가죽 연구","mis":"SC4-1-u4-X48"},{"t":"원생생물 — 포자로 새 품종 연구","mis":"SC4-1-u4-X48"},{"t":"균류 — 바닷물을 붉게 만드는 연구","mis":"SC4-1-u4-X48"}],"explanation":["무리마다 특징이 달라요.","곰팡이가 만드는 물질이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
