INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#6','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C53',3,'ox','auto','세균 가운데에는 질병 치료에 도움을 주는 것도 있어요.',ARRAY['SC4-1-u4-X49']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C53","difficulty":3,"kind":"ox","stem":"세균 가운데에는 질병 치료에 도움을 주는 것도 있어요.","answer":"O","reason_options":[{"t":"이로운 세균을 걸러 내어 치료에 이용하는 연구가 있기 때문에","correct":true},{"t":"세균은 모두 몸에 해롭기 때문에","mis":"SC4-1-u4-X49"}],"mis":"SC4-1-u4-X49","explanation":["첨단 과학 이야기를 떠올려요.","치료를 도와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#7','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C52',3,'mc','auto','바이오 에너지 연구원이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C52","difficulty":3,"kind":"mc","stem":"바이오 에너지 연구원이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"동물·식물 자원으로 친환경 연료를 만든다","correct":true},{"t":"병과 해충에 강한 작물을 만든다","mis":"SC4-1-u4-X48"},{"t":"환자의 질병 정보를 분석한다","mis":"SC4-1-u4-X48"},{"t":"독성이 낮은 약을 만든다","mis":"SC4-1-u4-X48"}],"explanation":["에너지 갈래예요.","연료를 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#8','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C51',4,'mc','auto','친구가 「연구원은 실험실에서 혼자 생물만 들여다보니까 다른 분야와는 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C51","difficulty":4,"kind":"mc","stem":"친구가 「연구원은 실험실에서 혼자 생물만 들여다보니까 다른 분야와는 상관없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「요즘은 의료·환경·전자·기계 같은 다른 분야와 힘을 합해 더 다양한 연구를 해.」","correct":true},{"t":"「맞아, 혼자서만 연구해.」","mis":"SC4-1-u4-X47"},{"t":"「연구원은 사람만 연구해.」","mis":"SC4-1-u4-X47"},{"t":"「연구원은 눈에 보이는 생물만 연구해.」","mis":"SC4-1-u4-X47"}],"explanation":["함께 연구해요.","분야가 넓어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#9','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C54',4,'mc','auto','친구가 「연구원이 되어 하고 싶은 일에는 정답이 하나뿐이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X50']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C54","difficulty":4,"kind":"mc","stem":"친구가 「연구원이 되어 하고 싶은 일에는 정답이 하나뿐이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「정답은 없어. 내가 풀고 싶은 문제가 무엇인지 떠올리면 돼.」","correct":true},{"t":"「맞아, 정해진 답을 골라야 해.」","mis":"SC4-1-u4-X50"},{"t":"「약을 만드는 것만 정답이야.」","mis":"SC4-1-u4-X50"},{"t":"「연구원은 생각할 필요가 없어.」","mis":"SC4-1-u4-X50"}],"explanation":["사람마다 달라요.","내 문제를 떠올려요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_L08_challenge#10','sci',4,1,'u4','L08','g4_1_sci_u4_L08_challenge','lesson_challenge','SC4-1-u4-C54',4,'essay','teacher','의약품을 만드는 생명과학 연구원이 된다면 어떤 일을 하고 싶은지 쓰고, 이 단원에서 배운 생물 가운데 무엇을 이용할지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC4-1-u4-C54","difficulty":4,"kind":"essay","stem":"의약품을 만드는 생명과학 연구원이 된다면 어떤 일을 하고 싶은지 쓰고, 이 단원에서 배운 생물 가운데 무엇을 이용할지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 충치가 생기지 않게 하는 약을 만들고 싶다. 곰팡이나 세균 가운데 일부는 다른 세균이 자라지 못하게 하는 물질을 만들기 때문에 이런 물질을 찾아 이용하고 싶다.","scoring_points":["하고 싶은 일을 썼는가","이용할 생물을 골랐는가","그 생물의 특징과 까닭을 이었는가"]},"explanation":["정답은 없어요.","배운 생물을 떠올려요.","까닭도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#1','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C2',1,'mc','auto','솔빛반 일지 ①에서 강아지를 동물 칸에 넣은 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C2","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ①에서 강아지를 동물 칸에 넣은 까닭은 무엇인가요?","options":[{"t":"스스로 움직이기 때문에","correct":true},{"t":"뿌리가 있기 때문에","mis":"SC4-1-u4-X04"},{"t":"털 색깔이 갈색이기 때문에","mis":"SC4-1-u4-X04"},{"t":"물에 살기 때문에","mis":"SC4-1-u4-X04"}],"explanation":["둘째 줄을 읽어요.","스스로 다녀요.","첫 번째예요."],"asset":{"type":"passage","lines":["강아지·소나무·표고버섯·해캄·짚신벌레 카드를 나누었다.","강아지는 스스로 움직여 동물 칸에 넣었다.","소나무는 뿌리·줄기·잎이 있어 식물 칸에 넣었다.","친구 가 — 「버섯은 움직이지 않으니 식물 칸에 넣자.」"],"title":"솔빛반 일지 ① 생물 놀이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#2','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C13',1,'mc','auto','솔빛반 일지 ②에서 곰팡이가 핀 빵은 어디에 둔 빵인가요?',ARRAY['SC4-1-u4-X11','SC4-1-u4-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C13","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ②에서 곰팡이가 핀 빵은 어디에 둔 빵인가요?","options":[{"t":"따뜻하고 축축한 곳","correct":true},{"t":"바짝 마른 곳","mis":"SC4-1-u4-X11"},{"t":"두 곳 모두","mis":"SC4-1-u4-X11"},{"t":"어느 곳에도 피지 않았다","mis":"SC4-1-u4-X08"}],"explanation":["둘째 줄을 읽어요.","축축한 곳이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["식빵 두 조각을 따뜻하고 축축한 곳과 바짝 마른 곳에 두었다.","며칠 뒤 따뜻하고 축축한 곳의 빵에만 곰팡이가 피었다.","현미경으로 보니 가늘고 긴 실 모양이 얽혀 있었다.","친구 나 — 「곰팡이는 빵 속에서 저절로 생긴 거야.」"],"title":"솔빛반 일지 ② 빵에 핀 곰팡이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#3','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C16',1,'mc','auto','솔빛반 일지 ③의 ㉮는 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X18','SC4-1-u4-X03']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C16","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ③의 ㉮는 무엇인가요?","options":[{"t":"해캄","correct":true},{"t":"짚신벌레","mis":"SC4-1-u4-X17"},{"t":"곰팡이","mis":"SC4-1-u4-X18"},{"t":"소나무","mis":"SC4-1-u4-X03"}],"explanation":["첫 줄을 읽어요.","초록색 머리카락 모양이에요.","해캄이에요."],"asset":{"type":"passage","lines":["㉮ 초록색이고 가늘고 긴 머리카락 모양이며 미끌미끌했다.","㉯ 짚신 모양이고 가는 털로 헤엄쳐 다녔다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다.","친구 다 — 「㉮는 초록색이니까 식물이야.」"],"title":"솔빛반 일지 ③ 연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#4','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C25',1,'mc','auto','솔빛반 일지 ④의 ㉡과 같은 모양의 세균은 무엇인가요?',ARRAY['SC4-1-u4-X24','SC4-1-u4-X26']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C25","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ④의 ㉡과 같은 모양의 세균은 무엇인가요?","options":[{"t":"대장균","correct":true},{"t":"포도상구균","mis":"SC4-1-u4-X24"},{"t":"콜레라균","mis":"SC4-1-u4-X24"},{"t":"해캄","mis":"SC4-1-u4-X26"}],"explanation":["㉡은 막대 모양이에요.","막대 모양 세균이에요.","대장균이에요."],"asset":{"type":"passage","lines":["㉠ 공 모양이 포도송이처럼 이어진 세균","㉡ 길쭉한 막대 모양 세균","㉢ 용수철처럼 꼬인 나선 모양 세균","깨끗이 닦은 책상에서도 세균이 발견되었다.","친구 가 — 「세균은 더러운 곳에만 살아.」"],"title":"솔빛반 일지 ④ 세균 그림 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#5','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C30',1,'mc','auto','솔빛반 일지 ⑤에서 낙엽을 분해한 생물로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X27']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C30","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑤에서 낙엽을 분해한 생물로 알맞은 것은 무엇인가요?","options":[{"t":"균류와 세균","correct":true},{"t":"해캄과 미역","mis":"SC4-1-u4-X29"},{"t":"소나무","mis":"SC4-1-u4-X29"},{"t":"아무 생물도 분해하지 않았다","mis":"SC4-1-u4-X27"}],"explanation":["첫 줄을 읽어요.","분해하는 무리예요.","첫 번째예요."],"asset":{"type":"passage","lines":["숲에 쌓였던 낙엽이 시간이 지나 분해되었다.","메주에 핀 곰팡이로 된장을 만들었다.","바닷물이 붉게 변한 적조 현상 소식을 보았다.","냉장고 밖에 둔 잼에 곰팡이가 피었다.","친구 나 — 「이런 생물은 모두 사라지는 게 좋겠어.」"],"title":"솔빛반 일지 ⑤ 생물의 영향 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#6','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C38',1,'mc','auto','솔빛반 일지 ⑥에서 가방을 만드는 데 이용한 것은 무엇인가요?',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C38","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑥에서 가방을 만드는 데 이용한 것은 무엇인가요?","options":[{"t":"버섯의 균사","correct":true},{"t":"세균","mis":"SC4-1-u4-X36"},{"t":"원생생물","mis":"SC4-1-u4-X36"},{"t":"바닷물","mis":"SC4-1-u4-X36"}],"explanation":["첫 줄을 읽어요.","균사예요.","첫 번째예요."],"asset":{"type":"passage","lines":["버섯 균사로 만든 가방이 있었다.","원생생물로 만든 생물 연료가 있었다.","바다의 기름을 분해하는 세균 이야기가 있었다.","곰팡이가 만든 물질로 만든 항생제가 있었다.","친구 다 — 「어떤 곰팡이든 약을 만들 수 있겠다.」"],"title":"솔빛반 일지 ⑥ 생명과학 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#7','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C45',1,'mc','auto','솔빛반 일지 ⑦에서 홍보할 곳으로 정한 곳은 어디인가요?',ARRAY['SC4-1-u4-X44']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C45","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑦에서 홍보할 곳으로 정한 곳은 어디인가요?","options":[{"t":"학교 게시판","correct":true},{"t":"포스터","mis":"SC4-1-u4-X44"},{"t":"생물 농약","mis":"SC4-1-u4-X44"},{"t":"세균","mis":"SC4-1-u4-X44"}],"explanation":["셋째 줄을 읽어요.","붙일 곳이에요.","학교 게시판이에요."],"asset":{"type":"passage","lines":["소개할 사례로 생물 농약을 골랐다.","해충에게만 질병을 일으키는 세균으로 만든 농약이다.","학교 게시판에 포스터로 붙이기로 했다.","조사하고, 정리하고, 포스터를 만들었다.","친구 가 — 「인터넷 사진은 출처를 안 적어도 돼.」"],"title":"솔빛반 일지 ⑦ 생물 농약 홍보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#8','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C52',1,'mc','auto','솔빛반 일지 ⑧에서 버려지는 물질로 전기를 얻는 연구는 어느 갈래인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C52","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑧에서 버려지는 물질로 전기를 얻는 연구는 어느 갈래인가요?","options":[{"t":"바이오 에너지","correct":true},{"t":"새로운 품종","mis":"SC4-1-u4-X48"},{"t":"의약품","mis":"SC4-1-u4-X48"},{"t":"질병 분석","mis":"SC4-1-u4-X48"}],"explanation":["첫 줄을 읽어요.","전기를 얻어요.","바이오 에너지예요."],"asset":{"type":"passage","lines":["바이오 에너지 연구원은 버려지는 물질로 전기를 얻는다.","의약품 연구원은 독성이 낮은 약을 만든다.","어떤 연구원은 이로운 세균을 걸러 내어 치료에 쓴다.","친구 나 — 「세균은 늘 해로우니 치료에 쓸 수 없어.」"],"title":"솔빛반 일지 ⑧ 연구원 만나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
