INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#16','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C52',2,'mc','auto','새로운 품종을 개발하는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":16,"concept":"SC4-1-u4-C52","difficulty":2,"kind":"mc","stem":"새로운 품종을 개발하는 까닭은 무엇인가요?","options":[{"t":"미래의 식량 부족에 대비하기 위해","correct":true},{"t":"높은 건물을 짓기 위해","mis":"SC4-1-u4-X48"},{"t":"세균을 모두 없애기 위해","mis":"SC4-1-u4-X48"},{"t":"로켓을 만들기 위해","mis":"SC4-1-u4-X48"}],"explanation":["먹을거리 연구예요.","미래를 대비해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#17','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C4',3,'mc','auto','버섯과 소나무를 견줄 때 버섯을 식물로 넣지 않는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":17,"concept":"SC4-1-u4-C4","difficulty":3,"kind":"mc","stem":"버섯과 소나무를 견줄 때 버섯을 식물로 넣지 않는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"버섯의 갓·자루·균사는 잎·줄기·뿌리와 다르기 때문에","correct":true},{"t":"버섯은 걸어 다니기 때문에","mis":"SC4-1-u4-X04"},{"t":"버섯은 크기가 작기 때문에","mis":"SC4-1-u4-X04"},{"t":"버섯은 초록색이기 때문에","mis":"SC4-1-u4-X04"}],"explanation":["부분을 견줘요.","생김새는 비슷해도 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#18','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C22',3,'mc','auto','해캄에 대한 설명 가운데 옳지 않은 것은 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X16']::text[],false,'{"seq":18,"concept":"SC4-1-u4-C22","difficulty":3,"kind":"mc","stem":"해캄에 대한 설명 가운데 옳지 않은 것은 무엇인가요?","options":[{"t":"스스로 양분을 만들지 못한다","correct":true},{"t":"가늘고 긴 머리카락 모양이다","mis":"SC4-1-u4-X17"},{"t":"초록색이고 미끌미끌하다","mis":"SC4-1-u4-X17"},{"t":"연못이나 논에서 산다","mis":"SC4-1-u4-X16"}],"explanation":["하나씩 따져요.","해캄은 양분을 만들어요.","첫 번째가 옳지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#19','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C29',3,'mc','auto','세균이 늘어나기 좋은 조건으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X25','SC4-1-u4-X21']::text[],false,'{"seq":19,"concept":"SC4-1-u4-C29","difficulty":3,"kind":"mc","stem":"세균이 늘어나기 좋은 조건으로 알맞은 것은 무엇인가요?","options":[{"t":"따뜻하고 양분이 있는 곳","correct":true},{"t":"꽁꽁 언 곳","mis":"SC4-1-u4-X25"},{"t":"조건과 상관없이 어디나 같다","mis":"SC4-1-u4-X25"},{"t":"세균은 늘어나지 않는다","mis":"SC4-1-u4-X21"}],"explanation":["우유가 상한 곳을 떠올려요.","따뜻했어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#20','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C36',3,'mc','auto','물속의 원생생물이 모두 사라진다면 생길 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X33','SC4-1-u4-X28']::text[],false,'{"seq":20,"concept":"SC4-1-u4-C36","difficulty":3,"kind":"mc","stem":"물속의 원생생물이 모두 사라진다면 생길 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"물속 산소가 줄고 다른 생물의 먹이가 사라진다","correct":true},{"t":"물속 산소가 더 많아진다","mis":"SC4-1-u4-X29"},{"t":"물이 저절로 깨끗해진다","mis":"SC4-1-u4-X33"},{"t":"아무 일도 일어나지 않는다","mis":"SC4-1-u4-X28"}],"explanation":["원생생물이 하는 일을 떠올려요.","산소와 먹이예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#21','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C42',3,'mc','auto','질병을 치료하는 물질을 찾아내는 연구에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC4-1-u4-X35']::text[],false,'{"seq":21,"concept":"SC4-1-u4-C42","difficulty":3,"kind":"mc","stem":"질병을 치료하는 물질을 찾아내는 연구에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"매우 어렵고 오랜 시간이 걸린다","correct":true},{"t":"어떤 곰팡이로든 하루 만에 얻는다","mis":"SC4-1-u4-X35"},{"t":"세균에서는 절대 얻을 수 없다","mis":"SC4-1-u4-X35"},{"t":"연구가 전혀 필요 없다","mis":"SC4-1-u4-X35"}],"explanation":["아주 특별한 경우예요.","오래 걸려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#22','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C46',3,'mc','auto','소개 자료를 정리할 때 알맞은 방법은 무엇인가요?',ARRAY['SC4-1-u4-X43','SC4-1-u4-X40']::text[],false,'{"seq":22,"concept":"SC4-1-u4-C46","difficulty":3,"kind":"mc","stem":"소개 자료를 정리할 때 알맞은 방법은 무엇인가요?","options":[{"t":"생물의 특징과 이용되는 모습을 짧게 간추린다","correct":true},{"t":"아는 것을 모두 길게 쓴다","mis":"SC4-1-u4-X43"},{"t":"어려운 낱말을 많이 넣는다","mis":"SC4-1-u4-X43"},{"t":"조사 없이 바로 만든다","mis":"SC4-1-u4-X40"}],"explanation":["간단해야 해요.","짧게 간추려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#23','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C19',4,'mc','auto','친구가 「짚신벌레는 움직이니까 동물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X15','SC4-1-u4-X18','SC4-1-u4-X03']::text[],false,'{"seq":23,"concept":"SC4-1-u4-C19","difficulty":4,"kind":"mc","stem":"친구가 「짚신벌레는 움직이니까 동물이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「짚신벌레는 움직이지만 생김새가 단순하고 동물과 달라 원생생물이야.」","correct":true},{"t":"「맞아, 움직이면 모두 동물이야.」","mis":"SC4-1-u4-X15"},{"t":"「짚신벌레는 균류야.」","mis":"SC4-1-u4-X18"},{"t":"「짚신벌레는 식물이야.」","mis":"SC4-1-u4-X03"}],"explanation":["원생생물의 뜻을 떠올려요.","동물과 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#24','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C35',4,'mc','auto','친구가 「곰팡이가 핀 잼도 된장처럼 먹어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X32','SC4-1-u4-X28']::text[],false,'{"seq":24,"concept":"SC4-1-u4-C35","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이가 핀 잼도 된장처럼 먹어도 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「같은 곰팡이라도 종류에 따라 영향이 달라. 잼에 핀 곰팡이는 먹으면 안 돼.」","correct":true},{"t":"「맞아, 곰팡이는 모두 먹어도 돼.」","mis":"SC4-1-u4-X32"},{"t":"「곰팡이는 모두 먹으면 안 되니 된장도 먹지 마.」","mis":"SC4-1-u4-X32"},{"t":"「곰팡이는 우리와 관계없어.」","mis":"SC4-1-u4-X28"}],"explanation":["잼과 메주를 견줘요.","종류가 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_a#25','sci',4,1,'u4','','g4_1_sci_u4_review_a','unit_review','SC4-1-u4-C4',4,'essay','teacher','솔빛반 일지 ①을 보고 표고버섯을 어느 칸에 넣어야 할지 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u4-C4","difficulty":4,"kind":"essay","stem":"솔빛반 일지 ①을 보고 표고버섯을 어느 칸에 넣어야 할지 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 표고버섯은 그 밖의 생물 칸에 넣어야 한다. 버섯은 움직이지 않지만 뿌리·줄기·잎이 없어 식물이라고 하기 어렵다.","scoring_points":["그 밖의 생물 칸이라고 썼는가","뿌리·줄기·잎이 없음을 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","기준을 떠올려요.","고쳐 써요."],"asset":{"type":"passage","lines":["강아지·소나무·표고버섯·해캄·짚신벌레 카드를 나누었다.","강아지는 스스로 움직여 동물 칸에 넣었다.","소나무는 뿌리·줄기·잎이 있어 식물 칸에 넣었다.","친구 가 — 「버섯은 움직이지 않으니 식물 칸에 넣자.」"],"title":"솔빛반 일지 ① 생물 놀이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#1','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C4',1,'ox','auto','솔빛반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C4","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"버섯은 움직이지 않지만 뿌리·줄기·잎이 없어 식물이라고 하기 어렵기 때문에","correct":true},{"t":"움직이지 않는 생물은 모두 식물이기 때문에","mis":"SC4-1-u4-X02"}],"mis":"SC4-1-u4-X02","explanation":["뿌리·줄기·잎을 봐요.","버섯에는 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["강아지·소나무·표고버섯·해캄·짚신벌레 카드를 나누었다.","강아지는 스스로 움직여 동물 칸에 넣었다.","소나무는 뿌리·줄기·잎이 있어 식물 칸에 넣었다.","친구 가 — 「버섯은 움직이지 않으니 식물 칸에 넣자.」"],"title":"솔빛반 일지 ① 생물 놀이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#2','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C14',1,'ox','auto','솔빛반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u4-X08']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C14","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"눈에 보이지 않던 포자가 습하고 따뜻한 빵에서 자란 것이기 때문에","correct":true},{"t":"곰팡이는 아무것도 없던 곳에서 생기기 때문에","mis":"SC4-1-u4-X08"}],"mis":"SC4-1-u4-X08","explanation":["포자를 떠올려요.","눈에 안 보였어요.","그래서 X예요."],"asset":{"type":"passage","lines":["식빵 두 조각을 따뜻하고 축축한 곳과 바짝 마른 곳에 두었다.","며칠 뒤 따뜻하고 축축한 곳의 빵에만 곰팡이가 피었다.","현미경으로 보니 가늘고 긴 실 모양이 얽혀 있었다.","친구 나 — 「곰팡이는 빵 속에서 저절로 생긴 거야.」"],"title":"솔빛반 일지 ② 빵에 핀 곰팡이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#3','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C22',1,'ox','auto','솔빛반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC4-1-u4-X03']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C22","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"해캄은 초록색이어도 뿌리·줄기·잎이 없어 식물이라고 하기 어렵기 때문에","correct":true},{"t":"초록색 생물은 모두 식물이기 때문에","mis":"SC4-1-u4-X03"}],"mis":"SC4-1-u4-X03","explanation":["색깔은 기준이 아니에요.","뿌리·줄기·잎을 봐요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 초록색이고 가늘고 긴 머리카락 모양이며 미끌미끌했다.","㉯ 짚신 모양이고 가는 털로 헤엄쳐 다녔다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다.","친구 다 — 「㉮는 초록색이니까 식물이야.」"],"title":"솔빛반 일지 ③ 연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#4','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C27',1,'ox','auto','솔빛반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u4-X22']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C27","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"깨끗이 닦은 책상에서도 발견될 만큼 세균은 어디에나 살기 때문에","correct":true},{"t":"세균은 더러운 곳에서만 살기 때문에","mis":"SC4-1-u4-X22"}],"mis":"SC4-1-u4-X22","explanation":["넷째 줄을 읽어요.","깨끗한 곳에서도요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 공 모양이 포도송이처럼 이어진 세균","㉡ 길쭉한 막대 모양 세균","㉢ 용수철처럼 꼬인 나선 모양 세균","깨끗이 닦은 책상에서도 세균이 발견되었다.","친구 가 — 「세균은 더러운 곳에만 살아.」"],"title":"솔빛반 일지 ④ 세균 그림 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#5','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C36',1,'ox','auto','솔빛반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u4-X33']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C36","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"이 생물들이 사라지면 낙엽이 쌓이고 된장 같은 음식도 만들 수 없기 때문에","correct":true},{"t":"이 생물들은 해롭기만 하기 때문에","mis":"SC4-1-u4-X33"}],"mis":"SC4-1-u4-X33","explanation":["모두 사라진다면?","도움도 사라져요.","그래서 X예요."],"asset":{"type":"passage","lines":["숲에 쌓였던 낙엽이 시간이 지나 분해되었다.","메주에 핀 곰팡이로 된장을 만들었다.","바닷물이 붉게 변한 적조 현상 소식을 보았다.","냉장고 밖에 둔 잼에 곰팡이가 피었다.","친구 나 — 「이런 생물은 모두 사라지는 게 좋겠어.」"],"title":"솔빛반 일지 ⑤ 생물의 영향 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#6','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C42',1,'ox','auto','솔빛반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC4-1-u4-X35']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C42","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"약이 되는 물질은 일부 곰팡이에서만 얻을 수 있기 때문에","correct":true},{"t":"곰팡이는 모두 약이 되기 때문에","mis":"SC4-1-u4-X35"}],"mis":"SC4-1-u4-X35","explanation":["일부에서만이에요.","연구도 오래 걸려요.","그래서 X예요."],"asset":{"type":"passage","lines":["버섯 균사로 만든 가방이 있었다.","원생생물로 만든 생물 연료가 있었다.","바다의 기름을 분해하는 세균 이야기가 있었다.","곰팡이가 만든 물질로 만든 항생제가 있었다.","친구 다 — 「어떤 곰팡이든 약을 만들 수 있겠다.」"],"title":"솔빛반 일지 ⑥ 생명과학 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#7','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C47',1,'ox','auto','솔빛반 일지 ⑦의 친구 가의 말은 알맞아요.',ARRAY['SC4-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C47","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ⑦의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"사진과 자료를 가져온 곳을 밝혀야 믿을 수 있는 자료가 되기 때문에","correct":true},{"t":"인터넷 사진은 출처를 밝히지 않아도 되기 때문에","mis":"SC4-1-u4-X41"}],"mis":"SC4-1-u4-X41","explanation":["출처를 떠올려요.","꼭 밝혀요.","그래서 X예요."],"asset":{"type":"passage","lines":["소개할 사례로 생물 농약을 골랐다.","해충에게만 질병을 일으키는 세균으로 만든 농약이다.","학교 게시판에 포스터로 붙이기로 했다.","조사하고, 정리하고, 포스터를 만들었다.","친구 가 — 「인터넷 사진은 출처를 안 적어도 돼.」"],"title":"솔빛반 일지 ⑦ 생물 농약 홍보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#8','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C53',1,'ox','auto','솔빛반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC4-1-u4-X49']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C53","difficulty":1,"kind":"ox","stem":"솔빛반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"이로운 세균을 걸러 내어 질병 치료에 쓰는 연구가 있기 때문에","correct":true},{"t":"세균은 늘 해롭기 때문에","mis":"SC4-1-u4-X49"}],"mis":"SC4-1-u4-X49","explanation":["셋째 줄을 읽어요.","이로운 세균이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["바이오 에너지 연구원은 버려지는 물질로 전기를 얻는다.","의약품 연구원은 독성이 낮은 약을 만든다.","어떤 연구원은 이로운 세균을 걸러 내어 치료에 쓴다.","친구 나 — 「세균은 늘 해로우니 치료에 쓸 수 없어.」"],"title":"솔빛반 일지 ⑧ 연구원 만나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#9','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C3',2,'ox','auto','동물에도 식물에도 넣기 어려운 생물을 「그 밖의 생물」로 나눌 수 있어요.',ARRAY['SC4-1-u4-X01']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C3","difficulty":2,"kind":"ox","stem":"동물에도 식물에도 넣기 어려운 생물을 「그 밖의 생물」로 나눌 수 있어요.","answer":"O","reason_options":[{"t":"동물이나 식물과 다른 특징을 가진 생물이 있기 때문에","correct":true},{"t":"생물은 동물과 식물 두 가지뿐이기 때문에","mis":"SC4-1-u4-X01"}],"mis":"SC4-1-u4-X01","explanation":["카드 놀이를 떠올려요.","넣기 어려운 카드가 있었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#10','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C13',2,'ox','auto','바짝 마른 모래밭은 균류가 잘 자라는 곳이에요.',ARRAY['SC4-1-u4-X11']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C13","difficulty":2,"kind":"ox","stem":"바짝 마른 모래밭은 균류가 잘 자라는 곳이에요.","answer":"X","reason_options":[{"t":"균류는 습기가 많고 그늘지며 따뜻한 곳에서 잘 자라기 때문에","correct":true},{"t":"균류는 메마른 곳을 좋아하기 때문에","mis":"SC4-1-u4-X11"}],"mis":"SC4-1-u4-X11","explanation":["균류가 좋아하는 곳이에요.","축축한 곳이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#11','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C18',2,'ox','auto','짚신벌레는 스스로 양분을 만들고, 해캄은 스스로 움직여요.',ARRAY['SC4-1-u4-X17']::text[],false,'{"seq":11,"concept":"SC4-1-u4-C18","difficulty":2,"kind":"ox","stem":"짚신벌레는 스스로 양분을 만들고, 해캄은 스스로 움직여요.","answer":"X","reason_options":[{"t":"해캄이 스스로 양분을 만들고, 짚신벌레가 스스로 움직이기 때문에","correct":true},{"t":"두 생물의 특징은 서로 같기 때문에","mis":"SC4-1-u4-X17"}],"mis":"SC4-1-u4-X17","explanation":["뒤바뀌었어요.","헤엄치는 쪽은 누구?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#12','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C26',2,'ox','auto','세균은 원생생물보다 크기가 커요.',ARRAY['SC4-1-u4-X23']::text[],false,'{"seq":12,"concept":"SC4-1-u4-C26","difficulty":2,"kind":"ox","stem":"세균은 원생생물보다 크기가 커요.","answer":"X","reason_options":[{"t":"세균은 균류나 원생생물보다도 작기 때문에","correct":true},{"t":"세균은 맨눈으로 잘 보일 만큼 크기 때문에","mis":"SC4-1-u4-X23"}],"mis":"SC4-1-u4-X23","explanation":["크기를 견줘요.","세균이 가장 작아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#13','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C31',2,'ox','auto','요구르트는 세균을 이용해 만들어요.',ARRAY['SC4-1-u4-X31']::text[],false,'{"seq":13,"concept":"SC4-1-u4-C31","difficulty":2,"kind":"ox","stem":"요구르트는 세균을 이용해 만들어요.","answer":"O","reason_options":[{"t":"젖산균 같은 세균을 이용해 발효시키기 때문에","correct":true},{"t":"요구르트는 해캄으로 만들기 때문에","mis":"SC4-1-u4-X31"}],"mis":"SC4-1-u4-X31","explanation":["발효 음식이에요.","젖산균이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#14','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C40',2,'ox','auto','분해가 잘되는 친환경 플라스틱을 만드는 데 세균을 이용해요.',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":14,"concept":"SC4-1-u4-C40","difficulty":2,"kind":"ox","stem":"분해가 잘되는 친환경 플라스틱을 만드는 데 세균을 이용해요.","answer":"O","reason_options":[{"t":"세균의 성질을 이용해 자연에서 잘 분해되는 물질을 만들기 때문에","correct":true},{"t":"플라스틱은 버섯 균사로만 만들기 때문에","mis":"SC4-1-u4-X36"}],"mis":"SC4-1-u4-X36","explanation":["세균을 이용한 예예요.","자연에서 분해돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#15','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C47',2,'ox','auto','컴퓨터로 자료를 만든 뒤에는 로그아웃을 해요.',ARRAY['SC4-1-u4-X41']::text[],false,'{"seq":15,"concept":"SC4-1-u4-C47","difficulty":2,"kind":"ox","stem":"컴퓨터로 자료를 만든 뒤에는 로그아웃을 해요.","answer":"O","reason_options":[{"t":"다른 사람이 내 계정을 쓰지 못하게 하기 위해","correct":true},{"t":"로그아웃은 하지 않아도 아무 문제가 없기 때문에","mis":"SC4-1-u4-X41"}],"mis":"SC4-1-u4-X41","explanation":["내 계정을 지켜요.","나가기를 눌러요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#16','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C51',2,'ox','auto','생명과학 연구원은 사람만 연구하고 동물과 식물은 연구하지 않아요.',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":16,"concept":"SC4-1-u4-C51","difficulty":2,"kind":"ox","stem":"생명과학 연구원은 사람만 연구하고 동물과 식물은 연구하지 않아요.","answer":"X","reason_options":[{"t":"사람·동물·식물은 물론 눈에 보이지 않는 생물까지 연구하기 때문에","correct":true},{"t":"연구원은 사람만 연구하기 때문에","mis":"SC4-1-u4-X47"}],"mis":"SC4-1-u4-X47","explanation":["넓게 연구해요.","세균도 연구해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#17','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C14',3,'ox','auto','곰팡이 포자는 눈에 보이지 않을 만큼 작아서 공기 중에 떠다닐 수 있어요.',ARRAY['SC4-1-u4-X08']::text[],false,'{"seq":17,"concept":"SC4-1-u4-C14","difficulty":3,"kind":"ox","stem":"곰팡이 포자는 눈에 보이지 않을 만큼 작아서 공기 중에 떠다닐 수 있어요.","answer":"O","reason_options":[{"t":"그래서 습하고 따뜻한 곳에 내려앉으면 곰팡이가 자라기 때문에","correct":true},{"t":"포자는 커서 언제나 눈에 잘 보이기 때문에","mis":"SC4-1-u4-X08"}],"mis":"SC4-1-u4-X08","explanation":["포자의 크기를 떠올려요.","아주 작아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#18','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C19',3,'ox','auto','원생생물은 동물·식물·균류 가운데 어디에도 속하지 않아요.',ARRAY['SC4-1-u4-X15']::text[],false,'{"seq":18,"concept":"SC4-1-u4-C19","difficulty":3,"kind":"ox","stem":"원생생물은 동물·식물·균류 가운데 어디에도 속하지 않아요.","answer":"O","reason_options":[{"t":"생김새가 단순하고 동물·식물·균류와 특징이 다르기 때문에","correct":true},{"t":"원생생물은 모두 식물에 속하기 때문에","mis":"SC4-1-u4-X15"}],"mis":"SC4-1-u4-X15","explanation":["원생생물의 뜻이에요.","어디에도 넣기 어려워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#19','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C25',3,'ox','auto','세균은 생김새가 단순하지만 모양은 여러 가지예요.',ARRAY['SC4-1-u4-X24']::text[],false,'{"seq":19,"concept":"SC4-1-u4-C25","difficulty":3,"kind":"ox","stem":"세균은 생김새가 단순하지만 모양은 여러 가지예요.","answer":"O","reason_options":[{"t":"공·막대·나선 등 여러 모양의 세균이 있기 때문에","correct":true},{"t":"세균은 모두 공 모양이기 때문에","mis":"SC4-1-u4-X24"}],"mis":"SC4-1-u4-X24","explanation":["세균 그림을 떠올려요.","모양이 달랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#20','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C34',3,'ox','auto','적조 현상은 바다에 사는 일부 원생생물의 수가 갑자기 늘어나서 생겨요.',ARRAY['SC4-1-u4-X30']::text[],false,'{"seq":20,"concept":"SC4-1-u4-C34","difficulty":3,"kind":"ox","stem":"적조 현상은 바다에 사는 일부 원생생물의 수가 갑자기 늘어나서 생겨요.","answer":"O","reason_options":[{"t":"일부 원생생물이 너무 많아지면 바닷물이 붉게 변하기 때문에","correct":true},{"t":"적조 현상은 바닷물이 얼어서 생기기 때문에","mis":"SC4-1-u4-X30"}],"mis":"SC4-1-u4-X30","explanation":["적조 현상의 뜻이에요.","수가 갑자기 늘어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#21','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C39',3,'ox','auto','클로렐라는 원생생물로, 건강식품을 만드는 데 이용돼요.',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":21,"concept":"SC4-1-u4-C39","difficulty":3,"kind":"ox","stem":"클로렐라는 원생생물로, 건강식품을 만드는 데 이용돼요.","answer":"O","reason_options":[{"t":"원생생물인 클로렐라의 특징을 이용해 건강식품을 만들기 때문에","correct":true},{"t":"클로렐라는 세균이기 때문에","mis":"SC4-1-u4-X36"}],"mis":"SC4-1-u4-X36","explanation":["어느 무리일까요?","원생생물이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#22','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C49',3,'ox','auto','생물 농약은 특정한 해충에게만 작용해 다른 생물에게 피해를 주지 않아요.',ARRAY['SC4-1-u4-X45']::text[],false,'{"seq":22,"concept":"SC4-1-u4-C49","difficulty":3,"kind":"ox","stem":"생물 농약은 특정한 해충에게만 작용해 다른 생물에게 피해를 주지 않아요.","answer":"O","reason_options":[{"t":"해충에게만 질병을 일으키는 곰팡이나 세균을 이용하기 때문에","correct":true},{"t":"생물 농약은 모든 생물을 해치기 때문에","mis":"SC4-1-u4-X45"}],"mis":"SC4-1-u4-X45","explanation":["친환경 농약이에요.","해충에게만이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#23','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C14',4,'mc','auto','친구가 「곰팡이는 생물이 아니라 빵이 변한 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X08','SC4-1-u4-X07']::text[],false,'{"seq":23,"concept":"SC4-1-u4-C14","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이는 생물이 아니라 빵이 변한 거야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「눈에 안 보이던 포자가 빵에서 자란 것이고, 균사로 된 생물이야.」","correct":true},{"t":"「맞아, 빵이 곰팡이로 변해.」","mis":"SC4-1-u4-X08"},{"t":"「곰팡이는 먼지야.」","mis":"SC4-1-u4-X07"},{"t":"「곰팡이는 공기가 바뀐 거야.」","mis":"SC4-1-u4-X08"}],"explanation":["포자와 균사를 떠올려요.","살아 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#24','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C42',4,'mc','auto','친구가 「곰팡이에서 약을 얻었다니, 곰팡이는 모두 약이 되겠다.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X35','SC4-1-u4-X37','SC4-1-u4-X39']::text[],false,'{"seq":24,"concept":"SC4-1-u4-C42","difficulty":4,"kind":"mc","stem":"친구가 「곰팡이에서 약을 얻었다니, 곰팡이는 모두 약이 되겠다.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「약이 되는 물질은 일부에서만 찾을 수 있고, 찾는 데 오래 걸려.」","correct":true},{"t":"「맞아, 모든 곰팡이가 약이 돼.」","mis":"SC4-1-u4-X35"},{"t":"「약은 원생생물로만 만들어.」","mis":"SC4-1-u4-X37"},{"t":"「곰팡이는 생활에 쓸 수 없어.」","mis":"SC4-1-u4-X39"}],"explanation":["특별한 경우예요.","일부에서만이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_b#25','sci',4,1,'u4','','g4_1_sci_u4_review_b','unit_review','SC4-1-u4-C27',4,'essay','teacher','솔빛반 일지 ④를 보고 세균의 모양 세 가지를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u4-C27","difficulty":4,"kind":"essay","stem":"솔빛반 일지 ④를 보고 세균의 모양 세 가지를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 세균에는 공 모양, 막대 모양, 나선 모양이 있다. 세균은 더러운 곳뿐 아니라 깨끗이 닦은 책상처럼 우리 주변 어디에서나 산다.","scoring_points":["세 가지 모양을 썼는가","어디에나 산다고 썼는가","친구 가의 말을 바르게 고쳤는가"]},"explanation":["일지를 읽어요.","㉠~㉢이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["㉠ 공 모양이 포도송이처럼 이어진 세균","㉡ 길쭉한 막대 모양 세균","㉢ 용수철처럼 꼬인 나선 모양 세균","깨끗이 닦은 책상에서도 세균이 발견되었다.","친구 가 — 「세균은 더러운 곳에만 살아.」"],"title":"솔빛반 일지 ④ 세균 그림 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#1','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C3',1,'mc','auto','솔빛반 일지 ①의 카드 가운데 「그 밖의 생물」 칸에 넣을 것은 무엇인가요?',ARRAY['SC4-1-u4-X01','SC4-1-u4-X02','SC4-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C3","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ①의 카드 가운데 「그 밖의 생물」 칸에 넣을 것은 무엇인가요?","options":[{"t":"표고버섯, 해캄, 짚신벌레","correct":true},{"t":"강아지, 소나무","mis":"SC4-1-u4-X01"},{"t":"소나무, 표고버섯","mis":"SC4-1-u4-X02"},{"t":"강아지, 해캄","mis":"SC4-1-u4-X04"}],"explanation":["동물도 식물도 아닌 것이에요.","세 장이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["강아지·소나무·표고버섯·해캄·짚신벌레 카드를 나누었다.","강아지는 스스로 움직여 동물 칸에 넣었다.","소나무는 뿌리·줄기·잎이 있어 식물 칸에 넣었다.","친구 가 — 「버섯은 움직이지 않으니 식물 칸에 넣자.」"],"title":"솔빛반 일지 ① 생물 놀이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#2','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C9',1,'mc','auto','솔빛반 일지 ②에서 현미경으로 본 가늘고 긴 실 모양을 무엇이라고 하나요?',ARRAY['SC4-1-u4-X12','SC4-1-u4-X02','SC4-1-u4-X17']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C9","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ②에서 현미경으로 본 가늘고 긴 실 모양을 무엇이라고 하나요?","options":[{"t":"균사","correct":true},{"t":"포자","mis":"SC4-1-u4-X12"},{"t":"뿌리","mis":"SC4-1-u4-X02"},{"t":"털","mis":"SC4-1-u4-X17"}],"explanation":["셋째 줄을 읽어요.","실 모양이에요.","균사예요."],"asset":{"type":"passage","lines":["식빵 두 조각을 따뜻하고 축축한 곳과 바짝 마른 곳에 두었다.","며칠 뒤 따뜻하고 축축한 곳의 빵에만 곰팡이가 피었다.","현미경으로 보니 가늘고 긴 실 모양이 얽혀 있었다.","친구 나 — 「곰팡이는 빵 속에서 저절로 생긴 거야.」"],"title":"솔빛반 일지 ② 빵에 핀 곰팡이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#3','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C17',1,'mc','auto','솔빛반 일지 ③의 ㉯는 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X18','SC4-1-u4-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C17","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ③의 ㉯는 무엇인가요?","options":[{"t":"짚신벌레","correct":true},{"t":"해캄","mis":"SC4-1-u4-X17"},{"t":"버섯","mis":"SC4-1-u4-X18"},{"t":"붕어","mis":"SC4-1-u4-X15"}],"explanation":["둘째 줄을 읽어요.","짚신 모양이에요.","짚신벌레예요."],"asset":{"type":"passage","lines":["㉮ 초록색이고 가늘고 긴 머리카락 모양이며 미끌미끌했다.","㉯ 짚신 모양이고 가는 털로 헤엄쳐 다녔다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다.","친구 다 — 「㉮는 초록색이니까 식물이야.」"],"title":"솔빛반 일지 ③ 연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#4','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C25',1,'mc','auto','솔빛반 일지 ④의 ㉢은 어떤 모양인가요?',ARRAY['SC4-1-u4-X24']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C25","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ④의 ㉢은 어떤 모양인가요?","options":[{"t":"나선 모양","correct":true},{"t":"공 모양","mis":"SC4-1-u4-X24"},{"t":"막대 모양","mis":"SC4-1-u4-X24"},{"t":"실 모양","mis":"SC4-1-u4-X24"}],"explanation":["용수철을 떠올려요.","꼬여 있어요.","나선 모양이에요."],"asset":{"type":"passage","lines":["㉠ 공 모양이 포도송이처럼 이어진 세균","㉡ 길쭉한 막대 모양 세균","㉢ 용수철처럼 꼬인 나선 모양 세균","깨끗이 닦은 책상에서도 세균이 발견되었다.","친구 가 — 「세균은 더러운 곳에만 살아.」"],"title":"솔빛반 일지 ④ 세균 그림 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#5','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C34',1,'mc','auto','솔빛반 일지 ⑤에서 바닷물이 붉게 변한 현상을 일으킨 무리는 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C34","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑤에서 바닷물이 붉게 변한 현상을 일으킨 무리는 무엇인가요?","options":[{"t":"원생생물","correct":true},{"t":"균류","mis":"SC4-1-u4-X29"},{"t":"세균","mis":"SC4-1-u4-X29"},{"t":"식물","mis":"SC4-1-u4-X30"}],"explanation":["적조 현상이에요.","바다의 일부 생물이에요.","원생생물이에요."],"asset":{"type":"passage","lines":["숲에 쌓였던 낙엽이 시간이 지나 분해되었다.","메주에 핀 곰팡이로 된장을 만들었다.","바닷물이 붉게 변한 적조 현상 소식을 보았다.","냉장고 밖에 둔 잼에 곰팡이가 피었다.","친구 나 — 「이런 생물은 모두 사라지는 게 좋겠어.」"],"title":"솔빛반 일지 ⑤ 생물의 영향 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#6','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C40',1,'mc','auto','솔빛반 일지 ⑥에서 바다의 기름을 분해하는 생물은 무엇인가요?',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C40","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑥에서 바다의 기름을 분해하는 생물은 무엇인가요?","options":[{"t":"세균","correct":true},{"t":"버섯","mis":"SC4-1-u4-X36"},{"t":"해캄","mis":"SC4-1-u4-X36"},{"t":"짚신벌레","mis":"SC4-1-u4-X36"}],"explanation":["셋째 줄을 읽어요.","기름을 먹이로 삼아요.","세균이에요."],"asset":{"type":"passage","lines":["버섯 균사로 만든 가방이 있었다.","원생생물로 만든 생물 연료가 있었다.","바다의 기름을 분해하는 세균 이야기가 있었다.","곰팡이가 만든 물질로 만든 항생제가 있었다.","친구 다 — 「어떤 곰팡이든 약을 만들 수 있겠다.」"],"title":"솔빛반 일지 ⑥ 생명과학 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#7','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C46',1,'mc','auto','솔빛반 일지 ⑦에서 포스터를 만든 차례로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X40']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C46","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑦에서 포스터를 만든 차례로 알맞은 것은 무엇인가요?","options":[{"t":"조사하기 → 정리하기 → 만들기","correct":true},{"t":"만들기 → 정리하기 → 조사하기","mis":"SC4-1-u4-X40"},{"t":"정리하기 → 조사하기 → 만들기","mis":"SC4-1-u4-X40"},{"t":"만들기만 했다","mis":"SC4-1-u4-X40"}],"explanation":["넷째 줄을 읽어요.","조사부터예요.","첫 번째예요."],"asset":{"type":"passage","lines":["소개할 사례로 생물 농약을 골랐다.","해충에게만 질병을 일으키는 세균으로 만든 농약이다.","학교 게시판에 포스터로 붙이기로 했다.","조사하고, 정리하고, 포스터를 만들었다.","친구 가 — 「인터넷 사진은 출처를 안 적어도 돼.」"],"title":"솔빛반 일지 ⑦ 생물 농약 홍보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#8','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C52',1,'mc','auto','솔빛반 일지 ⑧에서 독성이 낮은 약을 만드는 연구는 어느 갈래인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C52","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑧에서 독성이 낮은 약을 만드는 연구는 어느 갈래인가요?","options":[{"t":"의약품","correct":true},{"t":"바이오 에너지","mis":"SC4-1-u4-X48"},{"t":"새로운 품종","mis":"SC4-1-u4-X48"},{"t":"질병 분석","mis":"SC4-1-u4-X48"}],"explanation":["둘째 줄을 읽어요.","약을 만들어요.","의약품이에요."],"asset":{"type":"passage","lines":["바이오 에너지 연구원은 버려지는 물질로 전기를 얻는다.","의약품 연구원은 독성이 낮은 약을 만든다.","어떤 연구원은 이로운 세균을 걸러 내어 치료에 쓴다.","친구 나 — 「세균은 늘 해로우니 치료에 쓸 수 없어.」"],"title":"솔빛반 일지 ⑧ 연구원 만나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
