INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#16','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C53',2,'mc','auto','대변을 연구하는 생명과학 연구원 이야기로 알 수 있는 것은 무엇인가요?',ARRAY['SC4-1-u4-X49','SC4-1-u4-X21','SC4-1-u4-X33']::text[],false,'{"seq":16,"concept":"SC4-1-u4-C53","difficulty":2,"kind":"mc","stem":"대변을 연구하는 생명과학 연구원 이야기로 알 수 있는 것은 무엇인가요?","options":[{"t":"세균 가운데 질병 치료에 도움을 주는 것도 있다","correct":true},{"t":"세균은 늘 해롭다","mis":"SC4-1-u4-X49"},{"t":"세균은 생물이 아니다","mis":"SC4-1-u4-X21"},{"t":"세균은 모두 없애야 한다","mis":"SC4-1-u4-X33"}],"explanation":["이로운 세균을 떠올려요.","치료를 도와요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#17','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C13',3,'mc','auto','장마철에 곰팡이가 피지 않게 하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X11','SC4-1-u4-X08']::text[],false,'{"seq":17,"concept":"SC4-1-u4-C13","difficulty":3,"kind":"mc","stem":"장마철에 곰팡이가 피지 않게 하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"창문을 열어 습기를 줄이고 바람이 통하게 한다","correct":true},{"t":"물을 뿌려 축축하게 한다","mis":"SC4-1-u4-X11"},{"t":"따뜻하고 습하게 문을 꼭 닫아 둔다","mis":"SC4-1-u4-X11"},{"t":"곰팡이는 빵이 변한 것이니 그냥 둔다","mis":"SC4-1-u4-X08"}],"explanation":["균류가 싫어하는 곳이에요.","습기를 줄여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#18','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C17',3,'mc','auto','짚신벌레를 관찰하기 어려운 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X17','SC4-1-u4-X18','SC4-1-u4-X20']::text[],false,'{"seq":18,"concept":"SC4-1-u4-C17","difficulty":3,"kind":"mc","stem":"짚신벌레를 관찰하기 어려운 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"매우 작고 빠르게 움직이기 때문에","correct":true},{"t":"움직이지 않기 때문에","mis":"SC4-1-u4-X17"},{"t":"균사로 덮여 있기 때문에","mis":"SC4-1-u4-X18"},{"t":"살아 있지 않기 때문에","mis":"SC4-1-u4-X20"}],"explanation":["짚신벌레를 떠올려요.","헤엄쳐 다녀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#19','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C24',3,'mc','auto','다음 가운데 세균이 아닌 것은 무엇인가요?',ARRAY['SC4-1-u4-X26']::text[],false,'{"seq":19,"concept":"SC4-1-u4-C24","difficulty":3,"kind":"mc","stem":"다음 가운데 세균이 아닌 것은 무엇인가요?","options":[{"t":"해캄","correct":true},{"t":"대장균","mis":"SC4-1-u4-X26"},{"t":"젖산균","mis":"SC4-1-u4-X26"},{"t":"포도상구균","mis":"SC4-1-u4-X26"}],"explanation":["하나씩 따져요.","해캄은 원생생물이에요.","해캄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#20','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C31',3,'mc','auto','발효에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC4-1-u4-X30','SC4-1-u4-X27','SC4-1-u4-X31']::text[],false,'{"seq":20,"concept":"SC4-1-u4-C31","difficulty":3,"kind":"mc","stem":"발효에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"곰팡이나 세균을 이용해 유익한 식품을 만드는 과정이다","correct":true},{"t":"바닷물이 붉게 변하는 현상이다","mis":"SC4-1-u4-X30"},{"t":"죽은 생물이 그대로 쌓이는 현상이다","mis":"SC4-1-u4-X27"},{"t":"원생생물이 산소를 만드는 일이다","mis":"SC4-1-u4-X31"}],"explanation":["된장·김치를 떠올려요.","음식을 만들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#21','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C40',3,'mc','auto','세균의 특징을 이용한 생명과학 사례만 모은 것은 무엇인가요?',ARRAY['SC4-1-u4-X36']::text[],false,'{"seq":21,"concept":"SC4-1-u4-C40","difficulty":3,"kind":"mc","stem":"세균의 특징을 이용한 생명과학 사례만 모은 것은 무엇인가요?","options":[{"t":"인공눈, 기름 분해, 친환경 플라스틱","correct":true},{"t":"친환경 가죽, 항생제","mis":"SC4-1-u4-X36"},{"t":"생물 연료, 건강식품","mis":"SC4-1-u4-X36"},{"t":"친환경 가죽, 인공눈","mis":"SC4-1-u4-X36"}],"explanation":["세균 사례를 떠올려요.","세 가지예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#22','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C52',3,'mc','auto','병과 해충에 강한 작물을 만드는 연구가 우리 생활에 주는 도움은 무엇인가요?',ARRAY['SC4-1-u4-X48']::text[],false,'{"seq":22,"concept":"SC4-1-u4-C52","difficulty":3,"kind":"mc","stem":"병과 해충에 강한 작물을 만드는 연구가 우리 생활에 주는 도움은 무엇인가요?","options":[{"t":"먹을거리를 넉넉하게 얻을 수 있다","correct":true},{"t":"전기를 얻을 수 있다","mis":"SC4-1-u4-X48"},{"t":"독성이 낮은 약을 얻는다","mis":"SC4-1-u4-X48"},{"t":"질병 정보를 분석할 수 있다","mis":"SC4-1-u4-X48"}],"explanation":["작물 연구예요.","먹을거리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#23','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C29',4,'mc','auto','친구가 「세균은 아주 작으니까 금방 늘어나지는 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X21','SC4-1-u4-X25']::text[],false,'{"seq":23,"concept":"SC4-1-u4-C29","difficulty":4,"kind":"mc","stem":"친구가 「세균은 아주 작으니까 금방 늘어나지는 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「세균은 살기 좋은 조건이 되면 짧은 시간에 많은 수로 늘어나.」","correct":true},{"t":"「맞아, 세균은 늘어나지 않아.」","mis":"SC4-1-u4-X21"},{"t":"「세균은 차가울수록 빨리 늘어나.」","mis":"SC4-1-u4-X25"},{"t":"「세균은 늘 같은 빠르기로 늘어나.」","mis":"SC4-1-u4-X25"}],"explanation":["우유를 떠올려요.","하루 만에 상했어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#24','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C47',4,'mc','auto','친구가 「소개 자료가 재미있으면 확인 안 된 내용도 넣자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X41','SC4-1-u4-X43']::text[],false,'{"seq":24,"concept":"SC4-1-u4-C47","difficulty":4,"kind":"mc","stem":"친구가 「소개 자료가 재미있으면 확인 안 된 내용도 넣자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「옳은 정보인지 먼저 확인하고 출처를 밝힌 내용만 넣자.」","correct":true},{"t":"「좋아, 재미가 먼저야.」","mis":"SC4-1-u4-X41"},{"t":"「출처는 지우자.」","mis":"SC4-1-u4-X41"},{"t":"「어려운 낱말로 꽉 채우자.」","mis":"SC4-1-u4-X43"}],"explanation":["사실이 먼저예요.","출처도요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_c#25','sci',4,1,'u4','','g4_1_sci_u4_review_c','unit_review','SC4-1-u4-C36',4,'essay','teacher','솔빛반 일지 ⑤를 보고 이 생물들이 주는 도움과 어려움을 하나씩 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u4-C36","difficulty":4,"kind":"essay","stem":"솔빛반 일지 ⑤를 보고 이 생물들이 주는 도움과 어려움을 하나씩 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 도움은 곰팡이로 된장을 만드는 것이고, 어려움은 잼에 곰팡이가 피어 상하는 것이다. 이 생물들이 모두 사라지면 낙엽이 분해되지 않고 쌓이며 된장 같은 음식도 만들 수 없으므로 함께 살아가는 생물로 보아야 한다.","scoring_points":["도움을 하나 썼는가","어려움을 하나 썼는가","모두 사라지면 생길 일로 친구 나의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","양쪽을 다 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["숲에 쌓였던 낙엽이 시간이 지나 분해되었다.","메주에 핀 곰팡이로 된장을 만들었다.","바닷물이 붉게 변한 적조 현상 소식을 보았다.","냉장고 밖에 둔 잼에 곰팡이가 피었다.","친구 나 — 「이런 생물은 모두 사라지는 게 좋겠어.」"],"title":"솔빛반 일지 ⑤ 생물의 영향 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#1','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C2',1,'mc','auto','솔빛반 일지 ①에서 소나무를 식물 칸에 넣은 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC4-1-u4-C2","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ①에서 소나무를 식물 칸에 넣은 까닭은 무엇인가요?","options":[{"t":"뿌리·줄기·잎이 있기 때문에","correct":true},{"t":"스스로 움직이기 때문에","mis":"SC4-1-u4-X04"},{"t":"키가 크기 때문에","mis":"SC4-1-u4-X04"},{"t":"갈색이기 때문에","mis":"SC4-1-u4-X04"}],"explanation":["셋째 줄을 읽어요.","식물의 특징이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["강아지·소나무·표고버섯·해캄·짚신벌레 카드를 나누었다.","강아지는 스스로 움직여 동물 칸에 넣었다.","소나무는 뿌리·줄기·잎이 있어 식물 칸에 넣었다.","친구 가 — 「버섯은 움직이지 않으니 식물 칸에 넣자.」"],"title":"솔빛반 일지 ① 생물 놀이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#2','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C12',1,'mc','auto','솔빛반 일지 ②의 곰팡이는 어느 무리에 속하나요?',ARRAY['SC4-1-u4-X02','SC4-1-u4-X15','SC4-1-u4-X26']::text[],false,'{"seq":2,"concept":"SC4-1-u4-C12","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ②의 곰팡이는 어느 무리에 속하나요?","options":[{"t":"균류","correct":true},{"t":"식물","mis":"SC4-1-u4-X02"},{"t":"원생생물","mis":"SC4-1-u4-X15"},{"t":"세균","mis":"SC4-1-u4-X26"}],"explanation":["균사가 있어요.","버섯과 같은 무리예요.","균류예요."],"asset":{"type":"passage","lines":["식빵 두 조각을 따뜻하고 축축한 곳과 바짝 마른 곳에 두었다.","며칠 뒤 따뜻하고 축축한 곳의 빵에만 곰팡이가 피었다.","현미경으로 보니 가늘고 긴 실 모양이 얽혀 있었다.","친구 나 — 「곰팡이는 빵 속에서 저절로 생긴 거야.」"],"title":"솔빛반 일지 ② 빵에 핀 곰팡이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#3','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C19',1,'mc','auto','솔빛반 일지 ③의 ㉮와 ㉯는 어느 무리에 속하나요?',ARRAY['SC4-1-u4-X18','SC4-1-u4-X03','SC4-1-u4-X15']::text[],false,'{"seq":3,"concept":"SC4-1-u4-C19","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ③의 ㉮와 ㉯는 어느 무리에 속하나요?","options":[{"t":"원생생물","correct":true},{"t":"균류","mis":"SC4-1-u4-X18"},{"t":"식물","mis":"SC4-1-u4-X03"},{"t":"동물","mis":"SC4-1-u4-X15"}],"explanation":["연못에서 떠 왔어요.","생김새가 단순해요.","원생생물이에요."],"asset":{"type":"passage","lines":["㉮ 초록색이고 가늘고 긴 머리카락 모양이며 미끌미끌했다.","㉯ 짚신 모양이고 가는 털로 헤엄쳐 다녔다.","㉮와 ㉯ 모두 물이 고인 연못에서 떠 왔다.","친구 다 — 「㉮는 초록색이니까 식물이야.」"],"title":"솔빛반 일지 ③ 연못 물 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#4','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C26',1,'mc','auto','솔빛반 일지 ④처럼 세균을 그림 카드로 살펴본 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X23','SC4-1-u4-X21']::text[],false,'{"seq":4,"concept":"SC4-1-u4-C26","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ④처럼 세균을 그림 카드로 살펴본 까닭은 무엇인가요?","options":[{"t":"세균은 너무 작아 맨눈으로 볼 수 없기 때문에","correct":true},{"t":"세균은 버섯보다 크기 때문에","mis":"SC4-1-u4-X23"},{"t":"세균은 생물이 아니기 때문에","mis":"SC4-1-u4-X21"},{"t":"세균은 그림 속에만 살기 때문에","mis":"SC4-1-u4-X21"}],"explanation":["크기를 떠올려요.","아주 작아요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉠ 공 모양이 포도송이처럼 이어진 세균","㉡ 길쭉한 막대 모양 세균","㉢ 용수철처럼 꼬인 나선 모양 세균","깨끗이 닦은 책상에서도 세균이 발견되었다.","친구 가 — 「세균은 더러운 곳에만 살아.」"],"title":"솔빛반 일지 ④ 세균 그림 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#5','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C31',1,'mc','auto','솔빛반 일지 ⑤에서 된장을 만드는 데 이용한 생물은 무엇인가요?',ARRAY['SC4-1-u4-X29','SC4-1-u4-X30']::text[],false,'{"seq":5,"concept":"SC4-1-u4-C31","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑤에서 된장을 만드는 데 이용한 생물은 무엇인가요?","options":[{"t":"곰팡이","correct":true},{"t":"해캄","mis":"SC4-1-u4-X29"},{"t":"짚신벌레","mis":"SC4-1-u4-X29"},{"t":"적조를 일으키는 생물","mis":"SC4-1-u4-X30"}],"explanation":["둘째 줄을 읽어요.","메주에 핀 것이에요.","곰팡이예요."],"asset":{"type":"passage","lines":["숲에 쌓였던 낙엽이 시간이 지나 분해되었다.","메주에 핀 곰팡이로 된장을 만들었다.","바닷물이 붉게 변한 적조 현상 소식을 보았다.","냉장고 밖에 둔 잼에 곰팡이가 피었다.","친구 나 — 「이런 생물은 모두 사라지는 게 좋겠어.」"],"title":"솔빛반 일지 ⑤ 생물의 영향 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#6','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C41',1,'mc','auto','솔빛반 일지 ⑥에서 곰팡이가 만든 물질로 만든 것은 무엇인가요?',ARRAY['SC4-1-u4-X37']::text[],false,'{"seq":6,"concept":"SC4-1-u4-C41","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑥에서 곰팡이가 만든 물질로 만든 것은 무엇인가요?","options":[{"t":"항생제","correct":true},{"t":"생물 연료","mis":"SC4-1-u4-X37"},{"t":"친환경 가죽","mis":"SC4-1-u4-X37"},{"t":"인공눈","mis":"SC4-1-u4-X37"}],"explanation":["넷째 줄을 읽어요.","병을 치료해요.","항생제예요."],"asset":{"type":"passage","lines":["버섯 균사로 만든 가방이 있었다.","원생생물로 만든 생물 연료가 있었다.","바다의 기름을 분해하는 세균 이야기가 있었다.","곰팡이가 만든 물질로 만든 항생제가 있었다.","친구 다 — 「어떤 곰팡이든 약을 만들 수 있겠다.」"],"title":"솔빛반 일지 ⑥ 생명과학 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#7','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C49',1,'mc','auto','솔빛반 일지 ⑦의 생물 농약은 무엇을 이용해 만들었나요?',ARRAY['SC4-1-u4-X45']::text[],false,'{"seq":7,"concept":"SC4-1-u4-C49","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑦의 생물 농약은 무엇을 이용해 만들었나요?","options":[{"t":"해충에게만 질병을 일으키는 세균","correct":true},{"t":"모든 곤충을 없애는 생물","mis":"SC4-1-u4-X45"},{"t":"해캄","mis":"SC4-1-u4-X45"},{"t":"바닷물","mis":"SC4-1-u4-X45"}],"explanation":["둘째 줄을 읽어요.","해충에게만이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["소개할 사례로 생물 농약을 골랐다.","해충에게만 질병을 일으키는 세균으로 만든 농약이다.","학교 게시판에 포스터로 붙이기로 했다.","조사하고, 정리하고, 포스터를 만들었다.","친구 가 — 「인터넷 사진은 출처를 안 적어도 돼.」"],"title":"솔빛반 일지 ⑦ 생물 농약 홍보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#8','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C51',1,'mc','auto','솔빛반 일지 ⑧의 연구원들이 공통으로 하는 일은 무엇인가요?',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":8,"concept":"SC4-1-u4-C51","difficulty":1,"kind":"mc","stem":"솔빛반 일지 ⑧의 연구원들이 공통으로 하는 일은 무엇인가요?","options":[{"t":"생물을 연구해 우리 생활에 도움을 준다","correct":true},{"t":"날씨를 예보한다","mis":"SC4-1-u4-X47"},{"t":"생물과 관계없는 기계만 만든다","mis":"SC4-1-u4-X47"},{"t":"화산을 연구한다","mis":"SC4-1-u4-X47"}],"explanation":["셋 다 생물을 연구해요.","생활에 도움을 줘요.","첫 번째예요."],"asset":{"type":"passage","lines":["바이오 에너지 연구원은 버려지는 물질로 전기를 얻는다.","의약품 연구원은 독성이 낮은 약을 만든다.","어떤 연구원은 이로운 세균을 걸러 내어 치료에 쓴다.","친구 나 — 「세균은 늘 해로우니 치료에 쓸 수 없어.」"],"title":"솔빛반 일지 ⑧ 연구원 만나기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#9','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C5',2,'mc','auto','해캄을 식물로 넣기 어려운 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X03','SC4-1-u4-X04']::text[],false,'{"seq":9,"concept":"SC4-1-u4-C5","difficulty":2,"kind":"mc","stem":"해캄을 식물로 넣기 어려운 까닭은 무엇인가요?","options":[{"t":"뿌리·줄기·잎이 없기 때문에","correct":true},{"t":"초록색이기 때문에","mis":"SC4-1-u4-X03"},{"t":"물에 살기 때문에","mis":"SC4-1-u4-X04"},{"t":"크기가 작기 때문에","mis":"SC4-1-u4-X04"}],"explanation":["식물에 있는 것을 떠올려요.","해캄에는 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#10','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C15',2,'mc','auto','곰팡이를 관찰할 때 냄새를 직접 맡지 않는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X14']::text[],false,'{"seq":10,"concept":"SC4-1-u4-C15","difficulty":2,"kind":"mc","stem":"곰팡이를 관찰할 때 냄새를 직접 맡지 않는 까닭은 무엇인가요?","options":[{"t":"곰팡이의 포자를 들이마실 수 있기 때문에","correct":true},{"t":"냄새가 아주 좋기 때문에","mis":"SC4-1-u4-X14"},{"t":"곰팡이가 놀라기 때문에","mis":"SC4-1-u4-X14"},{"t":"곰팡이는 냄새가 없기 때문에","mis":"SC4-1-u4-X14"}],"explanation":["포자는 아주 작아요.","코로 들어가요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
