INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#21','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C38',3,'mc','auto','버섯 균사로 친환경 가죽을 만들 수 있는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X36','SC4-1-u4-X38']::text[],false,'{"seq":21,"concept":"SC4-1-u4-C38","difficulty":3,"kind":"mc","stem":"버섯 균사로 친환경 가죽을 만들 수 있는 까닭은 무엇인가요?","options":[{"t":"균사가 촘촘하게 얽혀 튼튼하기 때문에","correct":true},{"t":"버섯이 동물이기 때문에","mis":"SC4-1-u4-X36"},{"t":"균사가 기름을 분해하기 때문에","mis":"SC4-1-u4-X38"},{"t":"균사가 산소를 만들기 때문에","mis":"SC4-1-u4-X38"}],"explanation":["균사의 특성이에요.","얽혀 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#22','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C51',3,'mc','auto','생명과학 연구원이 다른 분야와 힘을 합하는 까닭은 무엇인가요?',ARRAY['SC4-1-u4-X47']::text[],false,'{"seq":22,"concept":"SC4-1-u4-C51","difficulty":3,"kind":"mc","stem":"생명과학 연구원이 다른 분야와 힘을 합하는 까닭은 무엇인가요?","options":[{"t":"더 다양한 연구를 해 생활에 도움을 주기 위해","correct":true},{"t":"혼자서는 아무 연구도 할 수 없기 때문에","mis":"SC4-1-u4-X47"},{"t":"생물 연구를 그만두기 위해","mis":"SC4-1-u4-X47"},{"t":"사람만 연구하기 위해","mis":"SC4-1-u4-X47"}],"explanation":["함께하면 넓어져요.","도움이 커져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#23','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C30',4,'mc','auto','친구가 「숲의 낙엽이 분해되지 않고 그대로 있으면 좋겠어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X27','SC4-1-u4-X29','SC4-1-u4-X28']::text[],false,'{"seq":23,"concept":"SC4-1-u4-C30","difficulty":4,"kind":"mc","stem":"친구가 「숲의 낙엽이 분해되지 않고 그대로 있으면 좋겠어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「분해되지 않으면 낙엽과 죽은 생물이 쌓여. 분해 덕분에 다른 생물도 이용할 수 있어.」","correct":true},{"t":"「맞아, 분해는 나쁜 일이야.」","mis":"SC4-1-u4-X27"},{"t":"「낙엽은 원생생물이 분해해.」","mis":"SC4-1-u4-X29"},{"t":"「분해는 우리와 관계없어.」","mis":"SC4-1-u4-X28"}],"explanation":["분해가 없다면?","쌓이기만 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#24','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C53',4,'mc','auto','친구가 「세균은 몸에 들어오면 늘 병을 일으켜.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC4-1-u4-X49','SC4-1-u4-X21','SC4-1-u4-X33']::text[],false,'{"seq":24,"concept":"SC4-1-u4-C53","difficulty":4,"kind":"mc","stem":"친구가 「세균은 몸에 들어오면 늘 병을 일으켜.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「몸에 이로운 세균도 있어서 질병 치료에 이용하는 연구도 해.」","correct":true},{"t":"「맞아, 세균은 늘 병을 일으켜.」","mis":"SC4-1-u4-X49"},{"t":"「세균은 생물이 아니야.」","mis":"SC4-1-u4-X21"},{"t":"「세균은 모두 없애야 해.」","mis":"SC4-1-u4-X33"}],"explanation":["첨단 과학 이야기를 떠올려요.","이로운 세균이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_sci_u4_review_d#25','sci',4,1,'u4','','g4_1_sci_u4_review_d','unit_review','SC4-1-u4-C42',4,'essay','teacher','솔빛반 일지 ⑥을 보고 생명과학 사례 두 가지와 이용한 생물을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC4-1-u4-C42","difficulty":4,"kind":"essay","stem":"솔빛반 일지 ⑥을 보고 생명과학 사례 두 가지와 이용한 생물을 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 버섯 균사로 만든 가방, 세균으로 바다의 기름을 분해하는 것이 있다. 약이 되는 물질은 일부 곰팡이에서만 얻을 수 있고 오랜 연구가 필요하므로 아무 곰팡이로나 약을 만들 수는 없다.","scoring_points":["사례 두 가지를 썼는가","이용한 생물을 바르게 짝 지었는가","일부에서만 얻는다고 친구 다의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","사례와 생물이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["버섯 균사로 만든 가방이 있었다.","원생생물로 만든 생물 연료가 있었다.","바다의 기름을 분해하는 세균 이야기가 있었다.","곰팡이가 만든 물질로 만든 항생제가 있었다.","친구 다 — 「어떤 곰팡이든 약을 만들 수 있겠다.」"],"title":"솔빛반 일지 ⑥ 생명과학 전시회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
